ab": [{"ko": "다르다", "en": "to be different", "note": "adjective"}, {"ko": "지내다", "en": "to get along; to spend time; to live", "note": "verb"}], "analysis": [{"type": "grammar", "label": "~(으)ㄴ (adjective modifier)", "exp": "Adjective form used before a noun. 다르다 → 다른 동물 (different animals).", "example_in_sentence": "서로 다른 동물"}, {"type": "grammar", "label": "~지만", "exp": "connective: but; however; despite; contrast", "example_in_sentence": "동물이지만"}, {"type": "grammar", "label": "~ㄹ/을 수 있다", "exp": "auxiliary: can; able to; possibility", "example_in_sentence": "지낼 수 있어요"}]}], "version": "s1"}', vocab = '[{"ko": "침팬지", "en": "chimpanzee", "note": "animal noun"}, {"ko": "강아지", "en": "puppy; small dog", "note": "animal noun"}, {"ko": "처음", "en": "first time; for the first time", "note": "adverb"}, {"ko": "매우", "en": "very; extremely", "note": "adverb of degree"}, {"ko": "놀라다", "en": "to be surprised", "note": "past participle adjective (from 놀라다)"}, {"ko": "표정", "en": "facial expression", "note": "noun"}, {"ko": "조심스럽다", "en": "to be careful; cautious", "note": "adverb (from 조심스럽다)"}, {"ko": "다가가다", "en": "to approach; to draw near", "note": "verb"}, {"ko": "손", "en": "hand", "note": "body part noun"}, {"ko": "천천히", "en": "slowly", "note": "adverb"}, {"ko": "내밀다", "en": "to hold out; to extend", "note": "verb"}, {"ko": "냄새를 맡다", "en": "to smell; to catch a scent", "note": "fixed expression / collocation"}, {"ko": "무서워하다", "en": "to be scared; to fear", "note": "verb (from 무섭다)"}, {"ko": "가만히", "en": "still; quietly; motionlessly", "note": "adverb"}, {"ko": "동물", "en": "animal", "note": "noun"}, {"ko": "친구", "en": "friend", "note": "noun"}, {"ko": "서로", "en": "each other; mutually", "note": "adverb"}, {"ko": "부드럽다", "en": "to be gentle; soft", "note": "adverb (from 부드럽다)"}, {"ko": "만지다", "en": "to touch; to stroke", "note": "verb"}, {"ko": "사람", "en": "person; people", "note": "noun"}, {"ko": "모습", "en": "appearance; sight; scene", "note": "noun"}, {"ko": "감동하다", "en": "