update public.article_cache set translation = '{"texts": ["A pool staff member was working at a swimming pool in Brazil. A dog that always greeted him was nowhere to be seen.", "The staff member heard a strange sound. He lifted the pool cover.", "The dog was in the water. The staff member quickly pulled the dog out.", "The staff member performed CPR on the dog. After 2 minutes, the dog began breathing again."], "sentences": [{"text": "브라질에서 수영장 직원이 일을 하고 있었어요.", "translation": "A pool staff member was working at a swimming pool in Brazil.", "vocab": [{"ko": "브라질", "en": "Brazil", "note": ""}, {"ko": "수영장", "en": "swimming pool", "note": ""}, {"ko": "직원", "en": "staff member", "note": ""}, {"ko": "일하다", "en": "to work", "note": ""}], "analysis": [{"type": "grammar", "label": "~에서 (location/source)", "exp": "particle marking location where action occurs. 브라질에서 = ''in Brazil''; attaches to noun.", "example_in_sentence": "브라질에서"}, {"type": "grammar", "label": "~이/가 (subject marker)", "exp": "subject particle. 직원 + 이 = the staff member (subject of the sentence).", "example_in_sentence": "직원이"}, {"type": "grammar", "label": "~을/를 (object marker)", "exp": "direct object particle. 일 + 을 = work (direct object of 하고).", "example_in_sentence": "일을"}, {"type": "grammar", "label": "~고 있다 (continuous)", "exp": "progressive aspect marking ongoing action. 하다 → 하고 있다 = ''is doing / was doing''. 하고 있었어요 shows past continuous.", "example_in_sentence": "하고 있었어요"}]}, {"text": "항상 인사하는 개가 보이지 않았어요.", "translation": "The dog that always greeted him was nowhere to be seen.", "vocab": [{"ko": "항상", "en": "always", "note": "adverb"}, {"ko": "인사하다", "en": "to greet", "note": ""}, {"ko": "개", "en": "dog", "note": ""}, {"ko": "보이다", "en": "to be seen / to appear", "note": ""}], "analysis": [{"type": "grammar", "label": "~는 (present verb modifier)", "exp": "present-tense verb modifier. 인사하다 → 인사하는 + 개 = ''the dog that greets / the dog (that) is greeting''.", "example_in_sentence": "인사하는 개"}, {"type": "grammar", "label": "~이/가 (subject marker)", "exp": "subject particle. 개 + 가 = the dog (subject of sentence).", "example_in_sentence": "개가"}, {"type": "grammar", "label": "~지 않다", "exp": "long-form negation. 보이다 + 지 않다 = ''not be seen / not appear''. 보이지 않았어요 = was not seen.", "example_in_sentence": "보이지 않았어요"}]}, {"text": "직원은 이상한 소리를 들었어요.", "translation": "The staff member heard a strange sound.", "vocab": [{"ko": "직원", "en": "staff member", "note": ""}, {"ko": "이상하다", "en": "to be strange", "note": ""}, {"ko": "소리", "en": "sound", "note": ""}, {"ko": "듣다", "en": "to hear", "note": "ㄷ-irregular"}], "analysis": [{"type": "grammar", "label": "~은/는 (topic marker)", "exp": "topic particle. 직원 + 은 = ''as for the staff member / the staff member (topic)''.", "example_in_sentence": "직원은"}, {"type": "grammar", "label": "~ㄴ/은 (past verb / present adj modifier)", "exp": "adjective past/present modifier. 이상하다 → 이상한 + 소리 = ''strange sound''.", "example_in_sentence": "이상한 소리"}, {"type": "grammar", "label": "~을/를 (object marker)", "exp": "direct object particle. 소리 + 를 = sound (direct object of 듣다).", "example_in_sentence": "소리를"}, {"type": "grammar", "label": "ㄷ 불규칙 (ㄷ → ㄹ before vowel)", "exp": "ㄷ-irregular consonant. 듣다 → 들었어요 (past). Before vowel: ㄷ → ㄹ.", "example_in_sentence": "들었어요"}]}, {"text": "수영장 덮개를 들어 올렸어요.", "translation": "He lifted the pool cover.", "vocab": [{"ko": "수영장", "en": "swimming pool", "note": ""}, {"ko": "덮개", "en": "cover", "note": ""}, {"ko": "들다", "en": "to lift / to raise", "note": ""}, {"ko": "올리다", "en": "to raise / to lift up", "note": ""}], "analysis": [{"type": "grammar", "label": "~을/를 (object marker)", "exp": "direct object particle. 덮개 + 를 = cover (direct object of 올리다).", "example_in_sentence": "덮개를"}, {"type": "grammar", "label": "~았/었어요", "exp": "Past tense polite ending. 올리다 → 올리었어요 → 올렸어요 (lifted).", "example_in_sentence": "올렸어요"}, {"type": "expression", "label": "들어 올리다", "exp": "fixed collocation: ''to lift up / to raise''. Combination of 들다 (lift) + 올리다 (raise). Common way to express raising something.", "example_in_sentence": "들어 올렸어요"}]}, {"text": "개가 물속에 있었어요.", "translation": "The dog was in the water.", "vocab": [{"ko": "개", "en": "dog", "note": ""}, {"ko": "물", "en": "water", "note": ""}, {"ko": "있다", "en": "to be / to exist", "note": "state verb"}], "analysis": [{"type": "grammar", "label": "~이/가 (subject marker)", "exp": "subject particle. 개 + 가 = the dog (subject).", "example_in_sentence": "개가"}, {"type": "grammar", "label": "~에 (location/time)", "exp": "particle marking static location. 물 + 속 + 에 = in/within the water. 물속 = 물 (water) + 속 (inside).", "example_in_sentence": "물속에"}, {"type": "grammar", "label": "~았/었어요", "exp": "Past tense polite ending. 있다 → 있었어요 (was).", "example_in_sentence": "있었어요"}]}, {"text": "직원은 개를 빨리 꺼냈어요.", "translation": "The staff member quickly pulled the dog out.", "vocab": [{"ko": "직원", "en": "staff member", "note": ""}, {"ko": "개", "en": "dog", "note": ""}, {"ko": "빨리", "en": "quickly", "note": "adverb"}, {"ko": "꺼내다", "en": "to pull out / to take out", "note": ""}], "analysis": [{"type": "grammar", "label": "~은/는 (topic marker)", "exp": "topic particle. 직원 + 은 = ''as for the staff member''.", "example_in_sentence": "직원은"}, {"type": "grammar", "label": "~을/를 (object marker)", "exp": "direct object particle. 개 + 를 = dog (direct object of 꺼내다).", "example_in_sentence": "개를"}, {"type": "grammar", "label": "~았/었/였어요 (past polite)", "exp": "past polite (vowel-contracted form). 꺼내다 + 었어요 → 꺼냈어요. Stem vowel ㅐ + 었 contracts: 꺼내 + 었 → 꺼냈.", "example_in_sentence": "꺼냈어요"}]}, {"text": "직원은 개에게 심폐소생술을 했어요.", "translation": "The staff member performed CPR on the dog.", "vocab": [{"ko": "직원", "en": "staff member", "note": ""}, {"ko": "개", "en": "dog", "note": ""}, {"ko": "심폐소생술", "en": "CPR / cardiopulmonary resuscitation", "note": ""}, {"ko": "하다", "en": "to do / to perform", "note": ""}], "analysis": [{"type": "grammar", "label": "~은/는 (topic marker)", "exp": "topic particle. 직원 + 은 = topic ''the staff member''.", "example_in_sentence": "직원은"}, {"type": "grammar", "label": "~에게/한테 (to person)", "exp": "indirect object particle for animate beings. 개 + 에게 = ''to/on the dog''. Marks recipient of action.", "example_in_sentence": "개에게"}, {"type": "grammar", "label": "~을/를 (object marker)", "exp": "direct object particle. 심폐소생술 + 을 = CPR (direct object of 하다).", "example_in_sentence": "심폐소생술을"}, {"type": "grammar", "label": "했어요 (하다 past polite)", "exp": "past polite of 하다. 하다 → 했어요 = ''did / performed (past polite)''.", "example_in_sentence": "했어요"}]}, {"text": "2분 후에 개가 다시 숨을 쉬기 시작했어요.", "translation": "After 2 minutes, the dog began breathing again.", "vocab": [{"ko": "분", "en": "minute", "note": ""}, {"ko": "후", "en": "after / later", "note": ""}, {"ko": "개", "en": "dog", "note": ""}, {"ko": "숨", "en": "breath", "note": ""}], "analysis": [{"type": "grammar", "label": "~에 (location/time)", "exp": "particle marking time point. 후 + 에 = at/after. 2분 후에 = ''after 2 minutes''.", "example_in_sentence": "후에"}, {"type": "grammar", "label": "~이/가 (subject marker)", "exp": "subject particle. 개 + 가 = the dog (subject of main clause).", "example_in_sentence": "개가"}, {"type": "grammar", "label": "~을/를 (object marker)", "exp": "direct object particle. 숨 + 을 = breath (direct object of 쉬다).", "example_in_sentence": "숨을"}, {"type": "grammar", "label": "~기 시작하다 (start V-ing)", "exp": "inceptive aspect: ''begin doing / start to do''. 쉬다 → 쉬기 시작하다 = ''start breathing / began to breathe''.", "example_in_sentence": "쉬기 시작했어요"}]}], "version": "s6"}', vocab = '[{"ko": "브라질", "en": "Brazil", "note": ""}, {"ko": "수영장", "en": "swimming pool", "note": ""}, {"ko": "직원", "en": "staff member", "note": ""}, {"ko": "일하다", "en": "to work", "note": ""}, {"ko": "항상", "en": "always", "note": "adverb"}, {"ko": "인사하다", "en": "to greet", "note": ""}, {"ko": "개", "en": "dog", "note": ""}, {"ko": "보이다", "en": "to be seen / to appear", "note": ""}, {"ko": "이상하다", "