update public.article_cache set translation = '{"texts": ["There is a beautiful road in Amsterdam, the Netherlands. This road is lined with plane trees stretching along its length.", "The branches of the trees meet above the road and create a natural tunnel. It looks like there''s a green roof.", "When you walk along this road, you can feel the coolness under the shade of the trees. Many people come to see this beautiful scenery.", "In spring and summer, the green leaves are even more beautiful. In autumn, they change to yellow and orange, showing another kind of beauty."], "sentences": [{"text": "네덜란드 암스테르담에 아름다운 길이 있어요.", "translation": "There is a beautiful road in Amsterdam, the Netherlands.", "vocab": [{"ko": "아름답다", "en": "to be beautiful", "note": ""}, {"ko": "길", "en": "road, path", "note": ""}], "analysis": [{"type": "grammar", "label": "~에 (location/time)", "exp": "static location particle. indicates where something exists or takes place. 암스테르담 → 암스테르담에", "example_in_sentence": "암스테르담에"}, {"type": "expression", "label": "~이/가 있다", "exp": "Means ''there is''. 길 + 이 있어요 = there is a road.", "example_in_sentence": "길이 있어요"}]}, {"text": "이 길에는 플라타너스 나무들이 길게 늘어서 있어요.", "translation": "This road is lined with plane trees stretching along its length.", "vocab": [{"ko": "플라타너스", "en": "plane tree (sycamore)", "note": ""}, {"ko": "늘어서다", "en": "to stand in a row; to line up", "note": ""}], "analysis": [{"type": "grammar", "label": "~아/어 있다", "exp": "Shows a state that continues. 늘어서다 → 늘어서 있어요 (are standing in a row).", "example_in_sentence": "늘어서 있어요"}, {"type": "grammar", "label": "~게 (adverbializer suffix)", "exp": "forms adverbs from adjectives/verbs. 길다 (long) → 길게 (lengthily, along the length)", "example_in_sentence": "길게"}, {"type": "grammar", "label": "~이/가 (subject marker)", "exp": "subject particle. 나무들 → 나무들이", "example_in_sentence": "나무들이"}, {"type": "grammar", "label": "~에는", "exp": "에 (at/on) + 는 (topic). 이 길에는 = on this road.", "example_in_sentence": "길에는"}]}, {"text": "나무들의 가지가 길 위에서 만나서 자연 터널을 만들어요.", "translation": "The branches of the trees meet above the road and create a natural tunnel.", "vocab": [{"ko": "가지", "en": "branch", "note": ""}, {"ko": "만나다", "en": "to meet", "note": ""}, {"ko": "자연", "en": "nature, natural", "note": ""}, {"ko": "터널", "en": "tunnel", "note": ""}], "analysis": [{"type": "grammar", "label": "~을/를 (object marker)", "exp": "direct object particle. 터널 → 터널을", "example_in_sentence": "터널을"}, {"type": "grammar", "label": "~이/가 (subject marker)", "exp": "subject particle. 가지 → 가지가", "example_in_sentence": "가지가"}, {"type": "grammar", "label": "~에서 (location/source)", "exp": "location of action particle. indicates where an action occurs. 길 위 → 길 위에서 (above/on the road)", "example_in_sentence": "길 위에서"}, {"type": "grammar", "label": "~의 (possessive)", "exp": "possessive/attributive particle. 나무 → 나무들의 (of the trees)", "example_in_sentence": "나무들의"}, {"type": "grammar", "label": "~아/어서 (cause / sequence)", "exp": "connective suffix expressing sequence. 만나다 → 만나서 (meet and then create)", "example_in_sentence": "만나서"}]}, {"text": "마치 초록색 지붕이 있는 것 같아요.", "translation": "It looks like there''s a green roof.", "vocab": [{"ko": "초록색", "en": "green (color)", "note": ""}, {"ko": "지붕", "en": "roof", "note": ""}], "analysis": [{"type": "grammar", "label": "~이/가 (subject marker)", "exp": "subject particle. 지붕 → 지붕이", "example_in_sentence": "지붕이"}, {"type": "grammar", "label": "~는 것 같다", "exp": "Means ''it seems like'' or ''it looks like''. 있다 → 있는 것 같아요 (it looks like there is).", "example_in_sentence": "있는 것 같아요"}]}, {"text": "이 길을 걸으면 나무 그늘 아래에서 시원함을 느낄 수 있어요.", "translation": "When you walk along this road, you can feel the coolness under the shade of the trees.", "vocab": [{"ko": "걷다", "en": "to walk", "note": "ㄷ-irregular"}, {"ko": "그늘", "en": "shade", "note": ""}, {"ko": "시원함", "en": "coolness, freshness", "note": ""}, {"ko": "느끼다", "en": "to feel, sense", "note": ""}], "analysis": [{"type": "grammar", "label": "~(으)ㄹ 수 있다", "exp": "Means ''can''. 느끼다 → 느낄 수 있어요 (can feel).", "example_in_sentence": "느낄 수 있어요"}, {"type": "grammar", "label": "~(으)면 (if/when)", "exp": "conditional. 걷다 → 걸으면 (when/if walk). ㄷ-irregular stem 걷 → 걸", "example_in_sentence": "걸으면"}, {"type": "grammar", "label": "~을/를 (object marker)", "exp": "direct object particle. 시원함 → 시원함을", "example_in_sentence": "시원함을"}, {"type": "grammar", "label": "~에서 (location/source)", "exp": "location of action particle. 아래 → 아래에서 (under/from under)", "example_in_sentence": "아래에서"}]}, {"text": "많은 사람들이 이 아름다운 풍경을 보러 와요.", "translation": "Many people come to see this beautiful scenery.", "vocab": [{"ko": "많다", "en": "to be many", "note": ""}, {"ko": "사람", "en": "person", "note": ""}, {"ko": "풍경", "en": "scenery, landscape", "note": ""}, {"ko": "보다", "en": "to see, watch", "note": ""}], "analysis": [{"type": "grammar", "label": "~(으)러 (purpose with movement)", "exp": "purpose verb + movement verb. indicates ''come/go to do''. 보다 → 보러 와요 (come to see)", "example_in_sentence": "보러 와요"}, {"type": "grammar", "label": "ㅂ irregular + ~(으)ㄴ", "exp": "아름답다 → 아름다운 풍경 (beautiful scenery): ㅂ becomes 우 before the modifier.", "example_in_sentence": "아름다운 풍경"}, {"type": "grammar", "label": "~을/를 (object marker)", "exp": "direct object particle. 풍경 → 풍경을", "example_in_sentence": "풍경을"}, {"type": "grammar", "label": "~이/가 (subject marker)", "exp": "subject particle. 사람들 → 사람들이", "example_in_sentence": "사람들이"}, {"type": "grammar", "label": "~(으)ㄴ (adjective modifier)", "exp": "Adjective form used before a noun. 많다 → 많은 사람들 (many people).", "example_in_sentence": "많은 사람들"}]}, {"text": "봄과 여름에는 초록색 잎이 더욱 예뻐요.", "translation": "In spring and summer, the green leaves are even more beautiful.", "vocab": [{"ko": "봄", "en": "spring (season)", "note": ""}, {"ko": "여름", "en": "summer", "note": ""}, {"ko": "잎", "en": "leaf", "note": ""}, {"ko": "예쁘다", "en": "to be pretty", "note": ""}], "analysis": [{"type": "grammar", "label": "~이/가 (subject marker)", "exp": "subject particle. 잎 → 잎이", "example_in_sentence": "잎이"}, {"type": "grammar", "label": "~에는", "exp": "에 (in) + 는 (topic). 봄과 여름에는 = in spring and summer.", "example_in_sentence": "봄과 여름에는"}, {"type": "grammar", "label": "~와/과", "exp": "Means ''and'' between nouns. 봄 + 과 + 여름 = spring and summer.", "example_in_sentence": "봄과 여름"}, {"type": "expression", "label": "더욱 + adjective", "exp": "더욱 means ''even more''. 더욱 예뻐요 = are even prettier.", "example_in_sentence": "더욱 예뻐요"}]}, {"text": "가을에는 노란색과 주황색으로 변해서 또 다른 아름다움을 보여줘요.", "translation": "In autumn, they change to yellow and orange, showing another kind of beauty.", "vocab": [{"ko": "가을", "en": "autumn, fall", "note": ""}, {"ko": "노란색", "en": "yellow", "note": ""}, {"ko": "주황색", "en": "orange (color)", "note": ""}, {"ko": "변하다", "en": "to change, transform", "note": ""}], "analysis": [{"type": "grammar", "label": "~아/어서 (cause / sequence)", "exp": "connective suffix expressing sequence. 변하다 → 변해서 (change and then show)", "example_in_sentence": "변해서"}, {"type": "grammar", "label": "~을/를 (object marker)", "exp": "direct object particle. 아름다움 → 아름다움을", "example_in_sentence": "아름다움을"}, {"type": "grammar", "label": "또 다른", "exp": "Means ''another'' or ''a different''. 또 다른 아름다움 = another kind of beauty.", "example_in_sentence": "또 다른 아름다움"}, {"type": "grammar", "label": "~과/와 (with/and)", "exp": "formal conjunction particle joining nouns. 노란색 + 과 + 주황색 (yellow and orange)", "example_in_sentence": "노란색과 주황색으로"}, {"type": "expression", "label": "~(으)로 변하다", "exp": "Means ''to change into''. 주황색으로 변해서 = changing to orange.", "example_in_sentence": "주황색으로 변해서"}, {"type": "expression", "label": "~을 보여주다", "exp": "to show/display something. give-benefactive verb. 아름다움을 보여줘요 = show beauty (to viewer)", "example_in_sentence": "아름다움을 보여줘요"}]}], "version": "s6"}', vocab = '[{"ko": "아름답다", "en": "to be beautiful", "note": ""}, {"ko": "길", "en": "road, path", "note": ""}, {"ko": "플라타너스", "en": "plane tree (sycamore)", "note": ""}, {"ko": "늘어서다", "en": "to stand in a row; to line up", "note": ""}, {"ko": "가지", "en": "branch", "note": ""}, {"ko": "만나다", "en": "to meet", "note": ""}, {"ko": "자연", "en": "nature, natural", "note": ""}, {"ko": "터널", "en": "tunnel", "note": ""}, {"ko": "초록색", "en": "green (color)", "note": ""}, {"ko": "지붕", "en": "roof", "note": ""}, {"ko": "걷다", "en": "to walk", "note": "ㄷ-irregular"}, {"ko": "그늘", "en": "shade", "note": ""}, {"ko": "시원함", "en": "coolness, freshness", "note": ""}, {"ko": "느끼다", "en": "to feel, sense", "note": ""}, {"ko": "많다", "en": "to be many", "note": ""}, {"ko": "사람", "en": "person", "note": ""}, {"ko": "풍경", "en": "scenery, landscape", "note": ""}, {"ko": "보다", "en": "to see, watch", "note": ""}, {"ko": "봄", "en": "spring (season)", "note": ""}, {"ko": "여름", "en": "summer", "note": ""}, {"ko": "잎", "en": "leaf", "note": ""}, {"ko": "예쁘다", "en": "to be pretty", "note": ""}, {"ko": "가을", "en": "autumn, fall", "note": ""}, {"ko": "노란색", "en": "yellow", "note": ""}, {"ko": "주황색", "en": "orange (color)", "note": ""}, {"ko": "변하다", "en": "to change, transform", "note": ""}]', grammar = '{"patterns": [{"name": "~에서 (location/source)", "level": "Beginner", "exp": "location of action particle. indicates where an action occurs. 길 위 → 길 위에서 (above/on the road)", "ex_ko": "네덜란드 암스테르담에 아름다운 길이 있어요.", "ex_en": "There is a beautiful road in Amsterdam, the Netherlands."}, {"name": "~아/어 있다", "level": "Beginner", "exp": "Shows a state that continues. 늘어서다 → 늘어서 있어요 (are standing in a row).", "ex_ko": "이 길에는 플라타너스 나무들이 길게 늘어서 있어요.", "ex_en": "This road is lined with plane trees stretching along its length."}, {"name": "~게 (adverbializer suffix)", "level": "Beginner", "exp": "forms adverbs from adjectives/verbs. 길다 (long) → 길게 (lengthily, along the length)", "ex_ko": "이 길에는 플라타너스 나무들이 길게 늘어서 있어요.", "ex_en": "This road is lined with plane trees stretching along its length."}, {"name": "~이/가 (subject marker)", "level": "Beginner", "exp": "subject particle. 나무들 → 나무들이", "ex_ko": "이 길에는 플라타너스 나무들이 길게 늘어서 있어요.", "ex_en": "This road is lined with plane trees stretching along its length."}, {"name": "~에는", "level": "Beginner", "exp": "에 (in) + 는 (topic). 봄과 여름에는 = in spring and summer.", "ex_ko": "이 길에는 플라타너스 나무들이 길게 늘어서 있어요.", "ex_en": "This road is lined with plane trees stretching along its length."}, {"name": "~을/를 (object marker)", "level": "Beginner", "exp": "direct object particle. 아름다움 → 아름다움을", "ex_ko": "나무들의 가지가 길 위에서 만나서 자연 터널을 만들어요.", "ex_en": "The branches of the trees meet above the road and create a natural tunnel."}, {"name": "~의 (possessive)", "level": "Beginner", "exp": "possessive/attributive particle. 나무 → 나무들의 (of the trees)", "ex_ko": "나무들의 가지가 길 위에서 만나서 자연 터널을 만들어요.", "ex_en": "The branches of the trees meet above the road and create a natural tunnel."}, {"name": "~아/어서 (cause / sequence)", "level": "Beginner", "exp": "connective suffix expressing sequence. 만나다 → 만나서 (meet and then create)", "ex_ko": "나무들의 가지가 길 위에서 만나서 자연 터널을 만들어요.", "ex_en": "The branches of the trees meet above the road and create a natural tunnel."}, {"name": "~는 것 같다", "level": "Beginner", "exp": "Means ''it seems like'' or ''it looks like''. 있다 → 있는 것 같아요 (it looks like there is).", "ex_ko": "마치 초록색 지붕이 있는 것 같아요.", "ex_en": "It looks like there''s a green roof."}, {"name": "~(으)ㄹ 수 있다", "level": "Beginner", "exp": "Means ''can''. 느끼다 → 느낄 수 있어요 (can feel).", "ex_ko": "이 길을 걸으면 나무 그늘 아래에서 시원함을 느낄 수 있어요.", "ex_en": "When you walk along this road, you can feel the coolness under the shade of the trees."}, {"name": "~(으)면 (if/when)", "level": "Beginner", "exp": "conditional. 걷다 → 걸으면 (when/if walk). ㄷ-irregular stem 걷 → 걸", "ex_ko": "이 길을 걸으면 나무 그늘 아래에서 시원함을 느낄 수 있어요.", "ex_en": "When you walk along this road, you can feel the coolness under the shade of the trees."}, {"name": "~(으)러 (purpose with movement)", "level": "Beginner", "exp": "purpose verb + movement verb. indicates ''come/go to do''. 보다 → 보러 와요 (come to see)", "ex_ko": "많은 사람들이 이 아름다운 풍경을 보러 와요.", "ex_en": "Many people come to see this beautiful scenery."}, {"name": "ㅂ irregular + ~(으)ㄴ", "level": "Beginner", "exp": "아름답다 → 아름다운 풍경 (beautiful scenery): ㅂ becomes 우 before the modifier.", "ex_ko": "많은 사람들이 이 아름다운 풍경을 보러 와요.", "ex_en": "Many people come to see this beautiful scenery."}, {"name": "~(으)ㄴ (adjective modifier)", "level": "Beginner", "exp": "Adjective form used before a noun. 많다 → 많은 사람들 (many people).", "ex_ko": "많은 사람들이 이 아름다운 풍경을 보러 와요.", "ex_en": "Many people come to see this beautiful scenery."}, {"name": "~와/과", "level": "Beginner", "exp": "Means ''and'' between nouns. 봄 + 과 + 여름 = spring and summer.", "ex_ko": "봄과 여름에는 초록색 잎이 더욱 예뻐요.", "ex_en": "In spring and summer, the green leaves are even more beautiful."}]}', updated_at = now() where article_id = 'mozuwq3nnjzm' and md5(translation) = 'a587c8016139807315c69aec8a03367d';
update public.article_cache set translation = '{"texts": ["A mosquito factory in Medellín, Colombia is drawing attention. The factory was funded by Bill Gates. It produces 40 million special mosquitoes every week.", "These mosquitoes carry a natural bacterium. Because of this bacterium, mosquitoes cannot transmit viruses to people. They are released outdoors through drones and bicycles.", "The released mosquitoes mate with wild mosquitoes. Through this process, the virus-blocking ability spreads. The entire mosquito population naturally undergoes a change."], "sentences": [{"text": "콜롬비아 메델린에 있는 모기 공장이 주목받고 있어요.", "translation": "A mosquito factory in Medellín, Colombia is drawing attention.", "vocab": [{"ko": "모기", "en": "mosquito", "note": ""}, {"ko": "공장", "en": "factory", "note": ""}, {"ko": "주목받다", "en": "to draw attention / to be noticed", "note": ""}], "analysis": [{"type": "grammar", "label": "~고 있다", "exp": "Shows something happening now. 주목받다 → 주목받고 있어요 (is drawing attention).", "example_in_sentence": "주목받고 있어요"}]}, {"text": "이 공장은 빌 게이츠가 자금을 지원했어요.", "translation": "The factory was funded by Bill Gates.", "vocab": [{"ko": "자금", "en": "fund / capital", "note": ""}, {"ko": "지원하다", "en": "to support / to fund", "note": ""}], "analysis": []}, {"text": "매주 4천만 마리의 특별한 모기를 생산해요.", "translation": "It produces 40 million special mosquitoes every week.", "vocab": [{"ko": "매주", "en": "every week", "note": ""}, {"ko": "마리", "en": "counter for animals", "note": ""}, {"ko": "특별하다", "en": "to be special", "note": ""}, {"ko": "생산하다", "en": "to produce", "note": ""}], "analysis": []}, {"text": "이 모기들은 자연적인 세균을 가지고 있어요.", "translation": "These mosquitoes carry a natural bacterium.", "vocab": [{"ko": "자연적", "en": "natural", "note": ""}, {"ko": "세균", "en": "bacterium / germ", "note": ""}, {"ko": "가지다", "en": "to have / to carry", "note": ""}], "analysis": [{"type": "grammar", "label": "~고 있다", "exp": "가지다 → 가지고 있다 (to have; to carry). Here it shows a state, not an action in progress.", "example_in_sentence": "가지고 있어요"}, {"type": "grammar", "label": "~적인", "exp": "Suffix that turns a noun into a describing word, like ''-al'' or ''-ic''. 자연 → 자연적인 (natural).", "example_in_sentence": "자연적인"}]}, {"text": "이 세균 때문에 모기가 사람에게 바이러스를 옮길 수 없어요.", "translation": "Because of this bacterium, mosquitoes cannot transmit viruses to people.", "vocab": [{"ko": "바이러스", "en": "virus", "note": ""}, {"ko": "옮기다", "en": "to transmit / to transfer", "note": ""}], "analysis": [{"type": "grammar", "label": "~ 때문에", "exp": "Means ''because of''. 세균 때문에 = because of the bacteria.", "example_in_sentence": "세균 때문에"}, {"type": "grammar", "label": "~(으)ㄹ 수 없다", "exp": "Means ''cannot''. 옮기다 → 옮길 수 없어요 (cannot transmit).", "example_in_sentence": "옮길 수 없어요"}]}, {"text": "드론과 자전거를 통해 야외로 방출돼요.", "translation": "They are released outdoors through drones and bicycles.", "vocab": [{"ko": "드론", "en": "drone", "note": ""}, {"ko": "자전거", "en": "bicycle", "note": ""}, {"ko": "통하다", "en": "to go through / to pass", "note": ""}, {"ko": "야외", "en": "outdoors / outdoor", "note": ""}], "analysis": [{"type": "grammar", "label": "~을/를 통해", "exp": "Means ''through'' or ''by means of''. 드론과 자전거를 통해 = by drones and bicycles.", "example_in_sentence": "자전거를 통해"}, {"type": "grammar", "label": "~(으)로", "exp": "Shows direction: ''to''. 야외로 = to the outdoors.", "example_in_sentence": "야외로"}]}, {"text": "방출된 모기들은 야생 모기와 교배해요.", "translation": "The released mosquitoes mate with wild mosquitoes.", "vocab": [{"ko": "방출되다", "en": "to be released", "note": ""}, {"ko": "야생", "en": "wild", "note": ""}, {"ko": "교배하다", "en": "to mate / to breed", "note": ""}], "analysis": [{"type": "grammar", "label": "~와/과 (with)", "exp": "Here 와 means ''with''. 야생 모기와 교배해요 = they mate with wild mosquitoes.", "example_in_sentence": "야생 모기와"}]}, {"text": "이 과정을 통해 바이러스 차단 능력이 퍼져나가요.", "translation": "Through this process, the virus-blocking ability spreads.", "vocab": [{"ko": "과정", "en": "process", "note": ""}, {"ko": "차단하다", "en": "to block / to cut off", "note": ""}, {"ko": "능력", "en": "ability / capacity", "note": ""}, {"ko": "퍼져나가다", "en": "to spread out", "note": ""}], "analysis": [{"type": "grammar", "label": "~을/를 통해", "exp": "Means ''through''. 과정을 통해 = through this process.", "example_in_sentence": "과정을 통해"}]}, {"text": "자연스럽게 모기 개체군 전체가 변화하게 돼요.", "translation": "Naturally, the entire mosquito population ends up changing.", "vocab": [{"ko": "자연스럽다", "en": "to be natural / to seem natural", "note": ""}, {"ko": "개체군", "en": "population (of organisms)", "note": ""}, {"ko": "전체", "en": "whole / entire", "note": ""}, {"ko": "변화하다", "en": "to change / to transform", "note": ""}], "analysis": [{"type": "grammar", "label": "~스럽다", "exp": "Suffix that makes a describing word from a noun. 자연 → 자연스럽다 (to be natural) → 자연스럽게 (naturally).", "example_in_sentence": "자연스럽게"}, {"type": "grammar", "label": "~게 되다", "exp": "Shows a change that happens as a result: ''come to; end up''. 변화하다 → 변화하게 돼요 (ends up changing).", "example_in_sentence": "변화하게 돼요"}]}], "version": "s6"}', vocab = '[{"ko": "모기", "en": "mosquito", "note": ""}, {"ko": "공장", "en": "factory", "note": ""}, {"ko": "주목받다", "en": "to draw attention / to be noticed", "note": ""}, {"ko": "자금", "en": "fund / capital", "note": ""}, {"ko": "지원하다", "en": "to support / to fund", "note": ""}, {"ko": "매주", "en": "every week", "note": ""}, {"ko": "마리", "en": "counter for animals", "note": ""}, {"ko": "특별하다", "en": "to be special", "note": ""}, {"ko": "생산하다", "en": "to produce", "note": ""}, {"ko": "자연적", "en": "natural", "note": ""}, {"ko": "세균", "en": "bacterium / germ", "note": ""}, {"ko": "가지다", "en": "to have / to carry", "note": ""}, {"ko": "바이러스", "en": "virus", "note": ""}, {"ko": "옮기다", "en": "to transmit / to transfer", "note": ""}, {"ko": "드론", "en": "drone", "note": ""}, {"ko": "자전거", "en": "bicycle", "note": ""}, {"ko": "통하다", "en": "to go through / to pass", "note": ""}, {"ko": "야외", "en": "outdoors / outdoor", "note": ""}, {"ko": "방출되다", "en": "to be released", "note": ""}, {"ko": "야생", "en": "wild", "note": ""}, {"ko": "교배하다", "en": "to mate / to breed", "note": ""}, {"ko": "과정", "en": "process", "note": ""}, {"ko": "차단하다", "en": "to block / to cut off", "note": ""}, {"ko": "능력", "en": "ability / capacity", "note": ""}, {"ko": "퍼져나가다", "en": "to spread out", "note": ""}, {"ko": "자연스럽다", "en": "to be natural / to seem natural", "note": ""}, {"ko": "개체군", "en": "population (of organisms)", "note": ""}, {"ko": "전체", "en": "whole / entire", "note": ""}, {"ko": "변화하다", "en": "to change / to transform", "note": ""}]', grammar = '{"patterns": [{"name": "~고 있다", "level": "Intermediate", "exp": "가지다 → 가지고 있다 (to have; to carry). Here it shows a state, not an action in progress.", "ex_ko": "콜롬비아 메델린에 있는 모기 공장이 주목받고 있어요.", "ex_en": "A mosquito factory in Medellín, Colombia is drawing attention."}, {"name": "~적인", "level": "Intermediate", "exp": "Suffix that turns a noun into a describing word, like ''-al'' or ''-ic''. 자연 → 자연적인 (natural).", "ex_ko": "이 모기들은 자연적인 세균을 가지고 있어요.", "ex_en": "These mosquitoes carry a natural bacterium."}, {"name": "~ 때문에", "level": "Intermediate", "exp": "Means ''because of''. 세균 때문에 = because of the bacteria.", "ex_ko": "이 세균 때문에 모기가 사람에게 바이러스를 옮길 수 없어요.", "ex_en": "Because of this bacterium, mosquitoes cannot transmit viruses to people."}, {"name": "~(으)ㄹ 수 없다", "level": "Intermediate", "exp": "Means ''cannot''. 옮기다 → 옮길 수 없어요 (cannot transmit).", "ex_ko": "이 세균 때문에 모기가 사람에게 바이러스를 옮길 수 없어요.", "ex_en": "Because of this bacterium, mosquitoes cannot transmit viruses to people."}, {"name": "~을/를 통해", "level": "Intermediate", "exp": "Means ''through'' or ''by means of''. 드론과 자전거를 통해 = by drones and bicycles.", "ex_ko": "드론과 자전거를 통해 야외로 방출돼요.", "ex_en": "They are released outdoors through drones and bicycles."}, {"name": "~(으)로", "level": "Intermediate", "exp": "Shows direction: ''to''. 야외로 = to the outdoors.", "ex_ko": "드론과 자전거를 통해 야외로 방출돼요.", "ex_en": "They are released outdoors through drones and bicycles."}, {"name": "~와/과 (with)", "level": "Intermediate", "exp": "Here 와 means ''with''. 야생 모기와 교배해요 = they mate with wild mosquitoes.", "ex_ko": "방출된 모기들은 야생 모기와 교배해요.", "ex_en": "The released mosquitoes mate with wild mosquitoes."}, {"name": "~스럽다", "level": "Intermediate", "exp": "Suffix that makes a describing word from a noun. 자연 → 자연스럽다 (to be natural) → 자연스럽게 (naturally).", "ex_ko": "자연스럽게 모기 개체군 전체가 변화하게 돼요.", "ex_en": "Naturally, the entire mosquito population ends up changing."}, {"name": "~게 되다", "level": "Intermediate", "exp": "Shows a change that happens as a result: ''come to; end up''. 변화하다 → 변화하게 돼요 (ends up changing).", "ex_ko": "자연스럽게 모기 개체군 전체가 변화하게 돼요.", "ex_en": "Naturally, the entire mosquito population ends up changing."}]}', updated_at = now() where article_id = 'mozuxjqffd9m' and md5(translation) = '92a9082b07ac272c230978222156cb6d';
update public.article_cache set translation = '{"sentences": [{"text": "베트남의 관광업이 2026년 초에 급속한 성장을 보이고 있어요.", "idx": 0, "translation": "Vietnam''s tourism industry is showing rapid growth in early 2026.", "vocab": [{"ko": "관광업", "en": "tourism industry", "note": "관광 (sightseeing) + 업 (industry/business)"}, {"ko": "급속하다", "en": "to be rapid", "note": "adjective form of 급속; commonly used with 성장"}, {"ko": "성장", "en": "growth, development", "note": ""}], "analysis": [{"type": "grammar", "label": "~을/를 보이다", "exp": "Means ''to show'' a trend or result. 성장을 보이다 = to show growth.", "example_in_sentence": "성장을 보이고 있어요"}, {"type": "grammar", "label": "~고 있다", "exp": "continuous or progressive aspect; ongoing state", "example_in_sentence": "보이고 있어요"}, {"type": "grammar", "label": "~ 초에", "exp": "초 means ''the beginning (of a period)''. 2026년 초에 = in early 2026.", "example_in_sentence": "2026년 초에"}]}, {"text": "수백만 명의 해외 관광객들이 베트남을 찾았습니다.", "idx": 1, "translation": "Millions of overseas tourists visited Vietnam.", "vocab": [{"ko": "수백만", "en": "millions", "note": "수 (number) + 백 (hundred) + 만 (ten thousand)"}, {"ko": "해외", "en": "overseas, abroad", "note": "해 (sea) + 외 (outside)"}, {"ko": "관광객", "en": "tourist", "note": "관광 (sightseeing) + 객 (person)"}], "analysis": [{"type": "grammar", "label": "~습니다", "exp": "Formal polite ending often used in news. 찾다 → 찾았습니다 (visited).", "example_in_sentence": "찾았습니다"}]}, {"text": "이러한 성장은 동남아시아 전체의 관광업 발전에도 도움을 주고 있어요.", "idx": 2, "translation": "This growth is also helping tourism develop across Southeast Asia as a whole.", "vocab": [{"ko": "성장", "en": "growth", "note": ""}, {"ko": "동남아시아", "en": "Southeast Asia", "note": "동남 (southeast) + 아시아"}, {"ko": "발전", "en": "development, progress", "note": ""}], "analysis": [{"type": "grammar", "label": "~에도", "exp": "에 (to) + 도 (also). 발전에도 도움을 주다 = to also help the development.", "example_in_sentence": "발전에도"}, {"type": "grammar", "label": "도움을 주다", "exp": "Means ''to help'' or ''to contribute to''. 주다 → 주고 있어요 (is helping).", "example_in_sentence": "도움을 주고 있어요"}]}, {"text": "베트남은 이제 세계적인 관광 목적지로 자리잡고 있습니다.", "idx": 3, "translation": "Vietnam is now establishing itself as a world-class tourist destination.", "vocab": [{"ko": "세계적", "en": "global; world-class", "note": "세계 (world) + 적 (suffix) + 인"}, {"ko": "목적지", "en": "destination", "note": "목적 (purpose) + 지 (place)"}, {"ko": "자리잡다", "en": "to establish oneself, to take root", "note": ""}], "analysis": [{"type": "grammar", "label": "~(으)로 자리잡다", "exp": "Means ''to become established as''. 목적지로 자리잡다 = to establish itself as a destination.", "example_in_sentence": "목적지로 자리잡고 있습니다"}]}, {"text": "한국에서도 베트남 여행에 대한 관심이 높아지고 있어요.", "idx": 4, "translation": "Interest in Vietnam travel is also rising in Korea.", "vocab": [{"ko": "관심", "en": "interest, concern", "note": ""}, {"ko": "높아지다", "en": "to rise, to increase, to grow high", "note": "높다 (high) + 아지다 (become)"}], "analysis": [{"type": "grammar", "label": "~에서도", "exp": "에서 (in) + 도 (also). 한국에서도 = in Korea too.", "example_in_sentence": "한국에서도"}, {"type": "grammar", "label": "~에 대한", "exp": "Means ''about'' before a noun. 베트남 여행에 대한 관심 = interest in travel to Vietnam.", "example_in_sentence": "여행에 대한 관심"}, {"type": "expression", "label": "관심이 높아지다", "exp": "Means ''interest is growing''. 높다 → 높아지다 (to get higher).", "example_in_sentence": "관심이 높아지고 있어요"}]}, {"text": "많은 한국 관광객들이 베트남의 아름다운 자연과 문화를 경험하려고 합니다.", "idx": 5, "translation": "Many Korean tourists are trying to experience Vietnam''s beautiful nature and culture.", "vocab": [{"ko": "아름답다", "en": "to be beautiful", "note": ""}, {"ko": "경험하다", "en": "to experience", "note": ""}], "analysis": [{"type": "grammar", "label": "~(으)려고 하다", "exp": "Shows intention: ''plan to'' or ''try to''. 경험하다 → 경험하려고 합니다 (want to experience).", "example_in_sentence": "경험하려고 합니다"}, {"type": "grammar", "label": "ㅂ irregular + ~(으)ㄴ", "exp": "아름답다 → 아름다운 (beautiful): ㅂ becomes 우 before the modifier.", "example_in_sentence": "아름다운 자연"}]}, {"text": "베트남 정부는 관광 인프라(기본 시설) 개선에 계속 투자하고 있어요.", "idx": 6, "translation": "The Vietnamese government is continuing to invest in improving tourism infrastructure (basic facilities).", "vocab": [{"ko": "정부", "en": "government", "note": ""}, {"ko": "인프라", "en": "infrastructure", "note": "English loanword"}, {"ko": "투자하다", "en": "to invest", "note": ""}], "analysis": [{"type": "grammar", "label": "~에 투자하다", "exp": "Means ''to invest in''. 개선에 투자하다 = to invest in improving (something).", "example_in_sentence": "개선에 계속 투자하고 있어요"}]}, {"text": "이런 노력들이 관광객 증가로 이어지고 있습니다.", "idx": 7, "translation": "These efforts are leading to an increase in tourists.", "vocab": [{"ko": "노력", "en": "effort, endeavor", "note": ""}, {"ko": "증가", "en": "increase, rise", "note": ""}], "analysis": [{"type": "grammar", "label": "~(으)로 이어지다", "exp": "Means ''to lead to''. 증가로 이어지다 = to lead to an increase.", "example_in_sentence": "증가로 이어지고 있습니다"}]}], "version": "s1"}', vocab = '[{"ko": "관광업", "en": "tourism industry", "note": "관광 (sightseeing) + 업 (industry/business)"}, {"ko": "급속하다", "en": "to be rapid", "note": "adjective form of 급속; commonly used with 성장"}, {"ko": "성장", "en": "growth, development", "note": ""}, {"ko": "수백만", "en": "millions", "note": "수 (number) + 백 (hundred) + 만 (ten thousand)"}, {"ko": "해외", "en": "overseas, abroad", "note": "해 (sea) + 외 (outside)"}, {"ko": "관광객", "en": "tourist", "note": "관광 (sightseeing) + 객 (person)"}, {"ko": "동남아시아", "en": "Southeast Asia", "note": "동남 (southeast) + 아시아"}, {"ko": "발전", "en": "development, progress", "note": ""}, {"ko": "세계적", "en": "global; world-class", "note": "세계 (world) + 적 (suffix) + 인"}, {"ko": "목적지", "en": "destination", "note": "목적 (purpose) + 지 (place)"}, {"ko": "자리잡다", "en": "to establish oneself, to take root", "note": ""}, {"ko": "관심", "en": "interest, concern", "note": ""}, {"ko": "높아지다", "en": "to rise, to increase, to grow high", "note": "높다 (high) + 아지다 (become)"}, {"ko": "아름답다", "en": "to be beautiful", "note": ""}, {"ko": "경험하다", "en": "to experience", "note": ""}, {"ko": "정부", "en": "government", "note": ""}, {"ko": "인프라", "en": "infrastructure", "note": "English loanword"}, {"ko": "투자하다", "en": "to invest", "note": ""}, {"ko": "노력", "en": "effort, endeavor", "note": ""}, {"ko": "증가", "en": "increase, rise", "note": ""}, {"ko": "이러한", "en": "such/this kind of", "note": ""}, {"ko": "도움", "en": "help/contribution", "note": ""}, {"ko": "여행", "en": "travel", "note": ""}, {"ko": "많은", "en": "many", "note": ""}, {"ko": "아름다운", "en": "beautiful", "note": ""}, {"ko": "자연", "en": "nature", "note": ""}, {"ko": "문화", "en": "culture", "note": ""}, {"ko": "개선", "en": "improvement", "note": ""}, {"ko": "투자", "en": "investment", "note": ""}, {"ko": "이어지다", "en": "to lead to/result in", "note": ""}]', grammar = '{"patterns": [{"name": "~을/를 보이다", "level": "Intermediate", "exp": "Means ''to show'' a trend or result. 성장을 보이다 = to show growth.", "ex_ko": "베트남의 관광업이 2026년 초에 급속한 성장을 보이고 있어요.", "ex_en": "Vietnam''s tourism industry is showing rapid growth in early 2026."}, {"name": "~고 있다", "level": "Intermediate", "exp": "continuous or progressive aspect; ongoing state", "ex_ko": "베트남의 관광업이 2026년 초에 급속한 성장을 보이고 있어요.", "ex_en": "Vietnam''s tourism industry is showing rapid growth in early 2026."}, {"name": "~ 초에", "level": "Intermediate", "exp": "초 means ''the beginning (of a period)''. 2026년 초에 = in early 2026.", "ex_ko": "베트남의 관광업이 2026년 초에 급속한 성장을 보이고 있어요.", "ex_en": "Vietnam''s tourism industry is showing rapid growth in early 2026."}, {"name": "~습니다", "level": "Intermediate", "exp": "Formal polite ending often used in news. 찾다 → 찾았습니다 (visited).", "ex_ko": "수백만 명의 해외 관광객들이 베트남을 찾았습니다.", "ex_en": "Millions of overseas tourists visited Vietnam."}, {"name": "~에도", "level": "Intermediate", "exp": "에 (to) + 도 (also). 발전에도 도움을 주다 = to also help the development.", "ex_ko": "이러한 성장은 동남아시아 전체의 관광업 발전에도 도움을 주고 있어요.", "ex_en": "This growth is also helping tourism develop across Southeast Asia as a whole."}, {"name": "도움을 주다", "level": "Intermediate", "exp": "Means ''to help'' or ''to contribute to''. 주다 → 주고 있어요 (is helping).", "ex_ko": "이러한 성장은 동남아시아 전체의 관광업 발전에도 도움을 주고 있어요.", "ex_en": "This growth is also helping tourism develop across Southeast Asia as a whole."}, {"name": "~(으)로 자리잡다", "level": "Intermediate", "exp": "Means ''to become established as''. 목적지로 자리잡다 = to establish itself as a destination.", "ex_ko": "베트남은 이제 세계적인 관광 목적지로 자리잡고 있습니다.", "ex_en": "Vietnam is now establishing itself as a world-class tourist destination."}, {"name": "~에서도", "level": "Intermediate", "exp": "에서 (in) + 도 (also). 한국에서도 = in Korea too.", "ex_ko": "한국에서도 베트남 여행에 대한 관심이 높아지고 있어요.", "ex_en": "Interest in Vietnam travel is also rising in Korea."}, {"name": "~에 대한", "level": "Intermediate", "exp": "Means ''about'' before a noun. 베트남 여행에 대한 관심 = interest in travel to Vietnam.", "ex_ko": "한국에서도 베트남 여행에 대한 관심이 높아지고 있어요.", "ex_en": "Interest in Vietnam travel is also rising in Korea."}, {"name": "~(으)려고 하다", "level": "Intermediate", "exp": "Shows intention: ''plan to'' or ''try to''. 경험하다 → 경험하려고 합니다 (want to experience).", "ex_ko": "많은 한국 관광객들이 베트남의 아름다운 자연과 문화를 경험하려고 합니다.", "ex_en": "Many Korean tourists are trying to experience Vietnam''s beautiful nature and culture."}, {"name": "ㅂ irregular + ~(으)ㄴ", "level": "Intermediate", "exp": "아름답다 → 아름다운 (beautiful): ㅂ becomes 우 before the modifier.", "ex_ko": "많은 한국 관광객들이 베트남의 아름다운 자연과 문화를 경험하려고 합니다.", "ex_en": "Many Korean tourists are trying to experience Vietnam''s beautiful nature and culture."}, {"name": "~에 투자하다", "level": "Intermediate", "exp": "Means ''to invest in''. 개선에 투자하다 = to invest in improving (something).", "ex_ko": "베트남 정부는 관광 인프라(기본 시설) 개선에 계속 투자하고 있어요.", "ex_en": "The Vietnamese government is continuing to invest in improving tourism infrastructure (basic facilities)."}, {"name": "~(으)로 이어지다", "level": "Intermediate", "exp": "Means ''to lead to''. 증가로 이어지다 = to lead to an increase.", "ex_ko": "이런 노력들이 관광