update public.article_cache set translation = '{"texts": ["One of the most extreme forms of parental care exists in nature: mothers being consumed by their own offspring.", "This behavior is called matriphagy and has been observed in some species of insects, worms, arachnids, and amphibians.", "Mothers provide their own bodies as the first meal for their young, thereby increasing their offspring''s chances of survival.", "This sacrificial behavior is a result of natural selection, as the survival of multiple offspring is more advantageous for species preservation than the survival of the individual mother."], "sentences": [{"text": "자연계에서 가장 극단적인 자식 돌봄 방법 중 하나가 있어요.", "translation": "One of the most extreme forms of parental care exists in nature.", "vocab": [{"ko": "자연계", "en": "natural world", "note": "the world of nature"}, {"ko": "극단적이다", "en": "to be extreme", "note": "very severe or intense"}, {"ko": "돌봄", "en": "care", "note": "taking care of someone"}], "analysis": [{"type": "grammar", "label": "~중 하나", "exp": "one of/among. Used to indicate one item from a group. 방법 (method) → 방법 중 하나 (one of the methods)", "example_in_sentence": "방법 중 하나가"}]}, {"text": "바로 어미가 자신의 새끼들에게 먹히는 것입니다.", "translation": "It is the mother being eaten by her own young.", "vocab": [{"ko": "어미", "en": "mother animal", "note": "female parent of animals"}, {"ko": "새끼", "en": "young animal", "note": "baby animal or offspring"}, {"ko": "먹히다", "en": "to be eaten", "note": "passive form of 먹다"}], "analysis": [{"type": "grammar", "label": "~는 것이다", "exp": "Explains what something is: ''it is (the act of)…''. 먹히다 → 먹히는 것입니다 (it is being eaten).", "example_in_sentence": "먹히는 것입니다"}]}, {"text": "이런 행동을 모식(母食)이라고 불러요.", "translation": "This behavior is called matriphagy.", "vocab": [{"ko": "행동", "en": "behavior", "note": "action or conduct"}, {"ko": "모식", "en": "matriphagy", "note": "母 (mother) + 食 (eating)"}, {"ko": "부르다", "en": "to call", "note": "to name or refer to as"}], "analysis": [{"type": "grammar", "label": "~(이)라고 부르다", "exp": "to call/name something. 모식 → 모식이라고 → 모식이라고 불러요", "example_in_sentence": "모식이라고 불러요"}]}, {"text": "곤충, 벌레, 거미류, 양서류의 일부 종에서 관찰됩니다.", "translation": "It has been observed in some species of insects, worms, arachnids, and amphibians.", "vocab": [{"ko": "곤충", "en": "insect", "note": "small six-legged creatures"}, {"ko": "거미류", "en": "arachnids", "note": "spiders and related creatures"}, {"ko": "양서류", "en": "amphibians", "note": "animals that live both on land and water"}, {"ko": "관찰되다", "en": "to be observed", "note": "to be watched or noticed"}], "analysis": []}, {"text": "어미는 자신의 몸을 새끼들의 첫 번째 먹이로 제공해요.", "translation": "Mothers provide their own bodies as the first meal for their young.", "vocab": [{"ko": "몸", "en": "body", "note": "physical body"}, {"ko": "먹이", "en": "food/prey", "note": "food for animals"}, {"ko": "제공하다", "en": "to provide", "note": "to supply or offer"}], "analysis": [{"type": "grammar", "label": "~(으)로", "exp": "particle indicating method, means, or role. 먹이 + 로 → 먹이로 (as food)", "example_in_sentence": "먹이로 제공해요"}]}, {"text": "이를 통해 새끼들이 생존할 확률을 높입니다.", "translation": "Through this, they increase their offspring''s chances of survival.", "vocab": [{"ko": "생존하다", "en": "to survive", "note": "to stay alive"}, {"ko": "확률", "en": "probability/chance", "note": "likelihood of something happening"}, {"ko": "높이다", "en": "to raise/increase", "note": "to make higher"}], "analysis": [{"type": "expression", "label": "~을/를 통해", "exp": "Means ''through'' or ''by means of''. 이를 통해 = through this.", "example_in_sentence": "이를 통해"}]}, {"text": "이런 희생적 행동은 자연 선택의 결과예요.", "translation": "This sacrificial behavior is a result of natural selection.", "vocab": [{"ko": "희생적이다", "en": "to be sacrificial", "note": "involving personal sacrifice"}, {"ko": "선택", "en": "selection/choice", "note": "act of choosing"}, {"ko": "결과", "en": "result", "note": "outcome or consequence"}], "analysis": []}, {"text": "어미 개체보다 여러 새끼들이 살아남는 것이 종족 보존에 더 유리하기 때문입니다.", "translation": "This is because the survival of multiple offspring is more advantageous for species preservation than the survival of the individual mother.", "vocab": [{"ko": "개체", "en": "individual", "note": "single organism"}, {"ko": "살아남다", "en": "to survive", "note": "to remain alive"}, {"ko": "종족", "en": "species", "note": "group of similar organisms"}, {"ko": "보존", "en": "preservation", "note": "keeping something safe"}], "analysis": [{"type": "grammar", "label": "~보다", "exp": "particle for comparison meaning ''than'' or ''compared to''. 개체 + 보다 → 개체보다 (than the individual)", "example_in_sentence": "어미 개체보다"}, {"type": "grammar", "label": "~기 때문이다", "exp": "because/due to. Indicates reason or cause. 유리하다 → 유리하기 → 유리하기 때문입니다", "example_in_sentence": "유리하기 때문입니다"}]}], "version": "s1"}', vocab = '[{"ko": "자연계", "en": "natural world", "note": "the world of nature"}, {"ko": "극단적이다", "en": "to be extreme", "note": "very severe or intense"}, {"ko": "돌봄", "en": "care", "note": "taking care of someone"}, {"ko": "어미", "en": "mother animal", "note": "female parent of animals"}, {"ko": "새끼", "en": "young animal", "note": "baby animal or offspring"}, {"ko": "먹히다", "en": "to be eaten", "note": "passive form of 먹다"}, {"ko": "행동", "en": "behavior", "note": "action or conduct"}, {"ko": "모식", "en": "matriphagy", "note": "母 (mother) + 食 (eating)"}, {"ko": "부르다", "en": "to call", "note": "to name or refer to as"}, {"ko": "곤충", "en": "insect", "note": "small six-legged creatures"}, {"ko": "거미류", "en": "arachnids", "note": "spiders and related creatures"}, {"ko": "양서류", "en": "amphibians", "note": "animals that live both on land and water"}, {"ko": "관찰되다", "en": "to be observed", "note": "to be watched or noticed"}, {"ko": "몸", "en": "body", "note": "physical body"}, {"ko": "먹이", "en": "food/prey", "note": "food for animals"}, {"ko": "제공하다", "en": "to provide", "note": "to supply or offer"}, {"ko": "생존하다", "en": "to survive", "note": "to stay alive"}, {"ko": "확률", "en": "probability/chance", "note": "likelihood of something happening"}, {"ko": "높이다", "en": "to raise/increase", "note": "to make higher"}, {"ko": "희생적이다", "en": "to be sacrificial", "note": "involving personal sacrifice"}, {"ko": "선택", "en": "selection/choice", "note": "act of choosing"}, {"ko": "결과", "en": "result", "note": "outcome or consequence"}, {"ko": "개체", "en": "individual", "note": "single organism"}, {"ko": "살아남다", "en": "to survive", "note": "to remain alive"}, {"ko": "종족", "en": "species", "note": "group of similar organisms"}, {"ko": "보존", "en": "preservation", "note": "keeping something safe"}]', grammar = '{"patterns": [{"name": "~중 하나", "level": "Intermediate", "exp": "one of/among. Used to indicate one item from a group. 방법 (method) → 방법 중 하나 (one of the methods)", "ex_ko": "자연계에서 가장 극단적인 자식 돌봄 방법 중 하나가 있어요.", "ex_en": "One of the most extreme forms of parental care exists in nature."}, {"name": "~는 것이다", "level": "Intermediate", "exp": "Explains what something is: ''it is (the act of)…''. 먹히다 → 먹히는 것입니다 (it is being eaten).", "ex_ko": "바로 어미가 자신의 새끼들에게 먹히는 것입니다.", "ex_en": "It is the mother being eaten by her own young."}, {"name": "~(이)라고 부르다", "level": "Intermediate", "exp": "to call/name something. 모식 → 모식이라고 → 모식이라고 불러요", "ex_ko": "이런 행동을 모식(母食)이라고 불러요.", "ex_en": "This behavior is called matriphagy."}, {"name": "~(으)로", "level": "Intermediate", "exp": "particle indicating method, means, or role. 먹이 + 로 → 먹이로 (as food)", "ex_ko": "어미는 자신의 몸을 새끼들의 첫 번째 먹이로 제공해요.", "ex_en": "Mothers provide their own bodies as the first meal for their young."}, {"name": "~보다", "level": "Intermediate", "exp": "particle for comparison meaning ''than'' or ''compared to''. 개체 + 보다 → 개체보다 (than the individual)", "ex_ko": "어미 개체보다 여러 새끼들이 살아남는 것이 종족 보존에 더 유리하기 때문입니다.", "ex_en": "This is because the survival of multiple offspring is more advantageous for species preservation than the survival of the individual mother."}, {"name": "~기 때문이다", "level": "Intermediate", "exp": "because/due to. Indicates reason or cause. 유리하다 → 유리하기 → 유리하기 때문입니다", "ex_ko": "어미 개체보다 여러 새끼들이 살아남는 것이 종족 보존에 더 유리하기 때문입니다.", "ex_en": "This is because the survival of multiple offspring is more advantageous for species preservation than the survival of the individual mother."}]}', updated_at = now() where article_id = 'mozw3bj1qy9r' and md5(translation) = '25f68af6764dffed80c80b1f49cdcdb8';
update public.article_cache set translation = '{"texts": ["A black hole is the most mysterious celestial body in the universe. Time and space bend around a black hole. Scientists have created a simulation that demonstrates this phenomenon. You can see what a black hole looks like in real time through a computer. This simulation is provided for free. Many people can easily learn about black holes. Physics laws work differently near a black hole. Time flows slowly and light bends as well.", "Korean Teacher Shortage Becomes Serious, School Classes Disrupted", "What is an \"anxiety bag\"? A Popular Trend", "The United States and China Resume Talks Over Trade Issues", "\"Talking Pig\" Becomes SNS Star", "Apple Greatly Improves iPhone Speed with New AI Chip"], "sentences": [{"text": "블랙홀(black hole)은 우주에서 가장 신비한 천체예요.", "translation": "A black hole is the most mysterious celestial body in the universe.", "vocab": [{"ko": "블랙홀", "en": "black hole"}, {"ko": "우주", "en": "universe"}, {"ko": "천체", "en": "celestial body"}, {"ko": "신비하다", "en": "to be mysterious"}], "analysis": [{"type": "grammar", "label": "~은/는", "exp": "Topic-marking particle. Indicates the subject of the sentence. 블랙홀 (black hole) → 블랙홀은 (as for a black hole).", "example_in_sentence": "블랙홀(black hole)은"}, {"type": "grammar", "label": "~에서", "exp": "Location particle indicating ''in'' or ''within''. 우주 (universe) → 우주에서 (in the universe).", "example_in_sentence": "우주에서"}, {"type": "grammar", "label": "~(으)ㄴ", "exp": "Descriptive verb/adjective ending. 신비하다 (to be mysterious) → 신비한 (mysterious).", "example_in_sentence": "신비한"}, {"type": "grammar", "label": "~예요", "exp": "Declarative copula (informal/polite). 천체 (celestial body) + 예요 (is). Expresses definition or state.", "example_in_sentence": "천체예요"}]}, {"text": "블랙홀 주변에서는 시간과 공간이 휘어져요.", "translation": "Around a black hole, time and space are bent.", "vocab": [{"ko": "주변", "en": "vicinity; surroundings"}, {"ko": "시간", "en": "time"}, {"ko": "공간", "en": "space"}, {"ko": "휘어지다", "en": "to bend; to curve"}], "analysis": [{"type": "grammar", "label": "~에서", "exp": "Location particle. 주변 (vicinity) + 에서 (in/at). Indicates where the action occurs.", "example_in_sentence": "주변에서는"}, {"type": "grammar", "label": "~과/와", "exp": "Conjunction particle meaning ''and''. Connects two nouns. 시간 (time) 과 공간 (and space).", "example_in_sentence": "시간과 공간이"}, {"type": "grammar", "label": "~이/가", "exp": "Subject particle. 공간 + 이 = space (is the subject).", "example_in_sentence": "공간이"}, {"type": "grammar", "label": "~아/어지다", "exp": "Shows a change of state: ''become''. 휘다 → 휘어지다 → 휘어져요 (gets bent).", "example_in_sentence": "휘어져요"}]}, {"text": "과학자들이 이 현상을 보여주는 시뮬레이션(simulation)을 만들었어요.", "translation": "Scientists created a simulation that shows this phenomenon.", "vocab": [{"ko": "과학자", "en": "scientist"}, {"ko": "현상", "en": "phenomenon"}, {"ko": "보여주다", "en": "to show"}, {"ko": "시뮬레이션", "en": "simulation"}], "analysis": [{"type": "grammar", "label": "~이", "exp": "Subject-marking particle. 과학자들 (scientists) + 이 (subject marker). Indicates the agent performing the action.", "example_in_sentence": "과학자들이"}, {"type": "grammar", "label": "~을/를", "exp": "Object-marking particle. 현상 (phenomenon) + 을 (object marker). Marks the direct object.", "example_in_sentence": "현상을"}, {"type": "grammar", "label": "~는", "exp": "Modifier form of present tense. 보여주다 (to show) → 보여주는 (showing/that shows). Modifies the following noun 시뮬레이션.", "example_in_sentence": "보여주는"}, {"type": "grammar", "label": "~았/었어요", "exp": "Past tense declarative. 만들다 (to make) → 만들었어요 (made). Indicates completed action.", "example_in_sentence": "만들었어요"}]}, {"text": "컴퓨터를 통해 블랙홀의 모습을 실시간으로 볼 수 있어요.", "translation": "Through a computer, one can see the appearance of a black hole in real time.", "vocab": [{"ko": "컴퓨터", "en": "computer"}, {"ko": "통하다", "en": "to go through; to pass through"}, {"ko": "모습", "en": "appearance; shape"}, {"ko": "실시간", "en": "real time"}], "analysis": [{"type": "grammar", "label": "~을/를 통해", "exp": "Expression of means/method. Indicates the medium or way through which something is done.", "example_in_sentence": "컴퓨터를 통해"}, {"type": "grammar", "label": "~의", "exp": "Possessive particle. Indicates possession or relationship. 블랙홀 (black hole) + 의 (of). Links 블랙홀 to 모습.", "example_in_sentence": "블랙홀의"}, {"type": "grammar", "label": "~을/를", "exp": "Object-marking particle. 모습 (appearance) + 을 (object marker).", "example_in_sentence": "모습을"}, {"type": "grammar", "label": "~(으)ㄹ 수 있다", "exp": "Means ''can''. 보다 → 볼 수 있어요 (can see).", "example_in_sentence": "볼 수 있어요"}]}, {"text": "이 시뮬레이션은 무료로 제공돼요.", "translation": "This simulation is provided for free.", "vocab": [{"ko": "시뮬레이션", "en": "simulation"}, {"ko": "무료", "en": "free; no charge"}, {"ko": "제공되다", "en": "to be provided"}], "analysis": [{"type": "grammar", "label": "~은/는", "exp": "Topic-marking particle. 시뮬레이션 (simulation) + 은 (topic marker). Indicates the topic of the sentence.", "example_in_sentence": "이 시뮬레이션은"}, {"type": "grammar", "label": "~로", "exp": "Adverbial particle indicating manner or state. 무료 (free) + 로 (in the manner of). Modifies the verb.", "example_in_sentence": "무료로"}, {"type": "grammar", "label": "~되다 (passive)", "exp": "되다 can make a 하다 verb passive. 제공하다 → 제공되다 → 제공돼요 (is provided).", "example_in_sentence": "제공돼요"}]}, {"text": "많은 사람들이 블랙홀에 대해 쉽게 배울 수 있어요.", "translation": "Many people can easily learn about black holes.", "vocab": [{"ko": "많다", "en": "to be many"}, {"ko": "사람", "en": "person"}, {"ko": "쉽다", "en": "to be easy"}], "analysis": [{"type": "grammar", "label": "~(으)ㄴ (adjective modifier)", "exp": "Adjective form used before a noun. 많다 → 많은 사람들 (many people).", "example_in_sentence": "많은"}, {"type": "grammar", "label": "~이", "exp": "Subject-marking particle. 사람들 (people) + 이 (subject marker).", "example_in_sentence": "사람들이"}, {"type": "grammar", "label": "~에 대해", "exp": "Expression indicating ''about'' or ''concerning''. Shows the target or subject of the action.", "example_in_sentence": "블랙홀에 대해"}, {"type": "grammar", "label": "~게", "exp": "Adverbial ending. 쉽다 (to be easy) → 쉽게 (easily). Converts adjective to adverb.", "example_in_sentence": "쉽게"}, {"type": "grammar", "label": "~(으)ㄹ 수 있다", "exp": "Means ''can''. 배우다 → 배울 수 있어요 (can learn).", "example_in_sentence": "배울 수 있어요"}]}, {"text": "블랙홀 근처에서는 물리 법칙이 다르게 작동해요.", "translation": "Near a black hole, physical laws operate differently.", "vocab": [{"ko": "근처", "en": "vicinity; nearby"}, {"ko": "물리", "en": "physics"}, {"ko": "법칙", "en": "law; rule"}, {"ko": "작동하다", "en": "to operate; to function"}], "analysis": [{"type": "grammar", "label": "~에서는", "exp": "Location particle with topic marking. 근처 (vicinity) + 에서 (in) + 는 (topic). Indicates location and contrasts with other places.", "example_in_sentence": "근처에서는"}, {"type": "grammar", "label": "~이", "exp": "Subject-marking particle. 법칙 (law) + 이 (subject marker).", "example_in_sentence": "법칙이"}, {"type": "grammar", "label": "~게", "exp": "Adverbial ending. 다르다 (to be different) → 다르게 (differently). Converts adjective to adverb.", "example_in_sentence": "다르게"}, {"type": "grammar", "label": "~해요", "exp": "Present tense declarative. 작동하다 (to operate) → 작동해요 (operates). Regular verb conjugation.", "example_in_sentence": "작동해요"}]}, {"text": "시간이 천천히 흐르고 빛도 휘어져요.", "translation": "Time flows slowly and light also bends.", "vocab": [{"ko": "시간", "en": "time"}, {"ko": "천천히", "en": "slowly"}, {"ko": "흐르다", "en": "to flow"}, {"ko": "빛", "en": "light"}], "analysis": [{"type": "grammar", "label": "~이", "exp": "Subject-marking particle. 시간 (time) + 이 (subject marker).", "example_in_sentence": "시간이"}, {"type": "grammar", "label": "~고", "exp": "Coordinate conjunction. Connects two actions/states: 흐르다 (to flow) and 휘어지다 (to bend). Shows parallel actions.", "example_in_sentence": "흐르고"}, {"type": "grammar", "label": "~도", "exp": "Particle meaning ''also'' or ''too''. 빛 (light) + 도 (also). Includes the noun in the preceding context.", "example_in_sentence": "빛도"}, {"type": "grammar", "label": "~아/어지다", "exp": "Shows a change of state: ''become''. 휘다 → 휘어지다 → 휘어져요 (gets bent).", "example_in_sentence": "휘어져요"}]}], "version": "s6"}', vocab = '[{"ko": "블랙홀", "en": "black hole", "note": ""}, {"ko": "우주", "en": "universe", "note": ""}, {"ko": "천체", "en": "celestial body", "note": ""}, {"ko": "신비하다", "en": "to be mysterious", "note": ""}, {"ko": "주변", "en": "vicinity; surroundings", "note": ""}, {"ko": "시간", "en": "time", "note": ""}, {"ko": "공간", "en": "space", "note": ""}, {"ko": "휘어지다", "en": "to bend; to curve", "note": ""}, {"ko": "과학자", "en": "scientist", "note": ""}, {"ko": "현상", "en": "phenomenon", "note": ""}, {"ko": "보여주다", "en": "to show", "note": ""}, {"ko": "시뮬레이션", "en": "simulation", "note": ""}, {"ko": "컴퓨터", "en": "computer", "note": ""}, {"ko": "통하다", "en": "to go through; to pass through", "note": ""}, {"ko": "모습", "en": "appearance; shape", "note": ""}, {"ko": "실시간", "en": "real time", "note": ""}, {"ko": "무료", "en": "free; no charge", "note": ""}, {"ko": "제공되다", "en": "to be provided", "note": ""}, {"ko": "많다", "en": "to be many", "note": ""}, {"ko": "사람", "en": "person", "note": ""}, {"ko": "쉽다", "en": "to be easy", "note": ""}, {"ko": "근처", "en": "vicinity; nearby", "note": ""}, {"ko": "물리", "en": "physics", "note": ""}, {"ko": "법칙", "en": "law; rule", "note": ""}, {"ko": "작동하다", "en": "to operate; to function", "note": ""}, {"ko": "천천히", "en": "slowly", "note": ""}, {"ko": "흐르다", "en": "to flow", "note": ""}, {"ko": "빛", "en": "light", "note": ""}, {"ko": "만들다", "en": "to make; to create", "note": ""}, {"ko": "보다", "en": "to see; to view", "note": ""}, {"ko": "배우다", "en": "to learn", "note": ""}]', grammar = '{"patterns": [{"name": "~은/는", "level": "Beginner", "exp": "Topic-marking particle. Indicates the subject of the sentence. 블랙홀 (black hole) → 블랙홀은 (as for a black hole).", "ex_ko": "블랙홀(black hole)은 우주에서 가장 신비한 천체예요.", "ex_en": "A black hole is the most mysterious celestial body in the universe."}, {"name": "~에서", "level": "Beginner", "exp": "Location particle indicating ''in'' or ''within''. 우주 (universe) → 우주에서 (in the universe).", "ex_ko": "블랙홀(black hole)은 우주에서 가장 신비한 천체예요.", "ex_en": "A black hole is the most mysterious celestial body in the universe."}, {"name": "~(으)ㄴ (adjective modifier)", "level": "Beginner", "exp": "Descriptive verb/adjective ending. 신비하다 (to be mysterious) → 신비한 (mysterious).", "ex_ko": "블랙홀(black hole)은 우주에서 가장 신비한 천체예요.", "ex_en": "A black hole is the most mysterious celestial body in the universe."}, {"name": "~예요", "level": "Beginner", "exp": "Declarative copula (informal/polite). 천체 (celestial body) + 예요 (is). Expresses definition or state.", "ex_ko": "블랙홀(black hole)은 우주에서 가장 신비한 천체예요.", "ex_en": "A black hole is the most mysterious celestial body in the universe."}, {"name": "~과/와", "level": "Beginner", "exp": "Conjunction particle meaning ''and''. Connects two nouns. 시간 (time) 과 공간 (and space).", "ex_ko": "블랙홀 주변에서는 시간과 공간이 휘어져요.", "ex_en": "Around a black hole, time and space are bent."}, {"name": "~이/가", "level": "Beginner", "exp": "Subject particle. 공간 + 이 = space (is the subject).", "ex_ko": "블랙홀 주변에서는 시간과 공간이 휘어져요.", "ex_en": "Around a black hole, time and space are bent."}, {"name": "~아/어지다", "level": "Beginner", "exp": "Shows a change of state: ''become''. 휘다 → 휘어지다 → 휘어져요 (gets bent).", "ex_ko": "블랙홀 주변에서는 시간과 공간이 휘어져요.", "ex_en": "Around a black hole, time and space are bent."}, {"name": "~이", "level": "Beginner", "exp": "Subject-marking particle. 과학자들 (scientists) + 이 (subject marker). Indicates the agent performing the action.", "ex_ko": "과학자들이 이 현상을 보여주는 시뮬레이션(simulation)을 만들었어요.", "ex_en": "Scientists created a simulation that shows this phenomenon."}, {"name": "~을/를", "level": "Beginner", "exp": "Object-marking particle. 현상 (phenomenon) + 을 (object marker). Marks the direct object.", "ex_ko": "과학자들이 이 현상을 보여주는 시뮬레이션(simulation)을 만들었어요.", "ex_en": "Scientists created a simulation that shows this phenomenon."}, {"name": "~는", "level": "Beginner", "exp": "Modifier form of present tense. 보여주다 (to show) → 보여주는 (showing/that shows). Modifies the following noun 시뮬레이션.", "ex_ko": "과학자들이 이 현상을 보여주는 시뮬레이션(simulation)을 만들었어요.", "ex_en": "Scientists created a simulation that shows this phenomenon."}, {"name": "~았/었어요", "level": "Beginner", "exp": "Past tense declarative. 만들다 (to make) → 만들었어요 (made). Indicates completed action.", "ex_ko": "과학자들이 이 현상을 보여주는 시뮬레이션(simulation)을 만들었어요.", "ex_en": "Scientists created a simulation that shows this phenomenon."}, {"name": "~을/를 통해", "level": "Beginner", "exp": "Expression of means/method. Indicates the medium or way through which something is done.", "ex_ko": "컴퓨터를 통해 블랙홀의 모습을 실시간으로 볼 수 있어요.", "ex_en": "Through a computer, one can see the appearance of a black hole in real time."}, {"name": "~의", "level": "Beginner", "exp": "Possessive particle. Indicates possession or relationship. 블랙홀 (black hole) + 의 (of). Links 블랙홀 to 모습.", "ex_ko": "컴퓨터를 통해 블랙홀의 모습을 실시간으로 볼 수 있어요.", "ex_en": "Through a computer, one can see the appearance of a black hole in real time."}, {"name": "~(으)ㄹ 수 있다", "level": "Beginner", "exp": "Means ''can''. 배우다 → 배울 수 있어요 (can learn).", "ex_ko": "컴퓨터를 통해 블랙홀의 모습을 실시간으로 볼 수 있어요.", "ex_en": "Through a computer, one can see the appearance of a black hole in real time."}, {"name": "~로", "level": "Beginner", "exp": "Adverbial particle indicating manner or state. 무료 (free) + 로 (in the manner of). Modifies the verb.", "ex_ko": "이 시뮬레이션은 무료로 제공돼요.", "ex_en": "This simulation is provided for free."}]}', updated_at = now() where article_id = 'mozwk91yd860' and md5(translation) = '22bad75a3c591f7c96035dfcd2dab782';
update public.article_cache set translation = '{"sentences": [{"text": "네팔에서 마타바르싱 총리는 자신의 조카인 정 바하두르에게 살해당했습니다.", "idx": 0, "translation": "In Nepal, Prime Minister Matabar Singh was killed by his nephew Jung Bahadur.", "vocab": [{"ko": "마타바르싱", "en": "Matabar Singh (proper noun)", "note": "Name of Nepalese PM"}, {"ko": "조카", "en": "nephew", "note": "male sibling''s child"}, {"ko": "살해당하다", "en": "to be killed/murdered", "note": "passive voice of 살해하다"}], "analysis": [{"type": "grammar", "label": "~인 + noun", "exp": "인 (from 이다) links two nouns: ''who is''. 자신의 조카인 정 바하두르 = Jung Bahadur, his own nephew.", "example_in_sentence": "자신의 조카인 정 바하두르"}, {"type": "grammar", "label": "~에게", "exp": "dative particle indicating the agent of an action in passive voice", "example_in_sentence": "정 바하두르에게"}, {"type": "grammar", "label": "~당하다", "exp": "Added to some nouns to mean ''to suffer'' an action (passive). 살해 → 살해당하다 (to be murdered).", "example_in_sentence": "살해당했습니다"}]}, {"text": "정 바하두르는 삼촌을 죽인 후 다른 총리도 살해했습니다.", "idx": 1, "translation": "Jung Bahadur killed his uncle and then also murdered another prime minister.", "vocab": [{"ko": "삼촌", "en": "uncle", "note": "father''s brother or mother''s brother"}, {"ko": "죽이다", "en": "to kill", "note": "active verb; past ~죽인"}, {"ko": "다른", "en": "other/different", "note": "adjective"}], "analysis": [{"type": "grammar", "label": "~(으)ㄴ 후", "exp": "Means ''after doing''. 죽이다 → 죽인 후 (after killing).", "example_in_sentence": "죽인 후"}, {"type": "grammar", "label": "~도 (additive particle)", "exp": "also/too; marks additional action or object", "example_in_sentence": "다른 총리도"}]}, {"text": "그는 1년 후에 자신이 총리가 되었습니다.", "idx": 2, "translation": "A year later, he himself became prime minister.", "vocab": [{"ko": "1년", "en": "one year", "note": "duration; pure Sino-Korean number"}, {"ko": "후", "en": "after; later", "note": "temporal adverbial"}, {"ko": "총리", "en": "prime minister", "note": "head of government"}], "analysis": [{"type": "grammar", "label": "time + 후에", "exp": "Means ''later'' after a length of time. 1년 후에 = one year later.", "example_in_sentence": "1년 후에"}, {"type": "grammar", "label": "~이 되다", "exp": "become; copular auxiliary marking state change", "example_in_sentence": "총리가 되었습니다"}]}, {"text": "이는 네팔 역사상 매우 충격적인 사건으로 기록되고 있습니다.", "idx": 3, "translation": "This is being recorded as a very shocking event in Nepalese history.", "vocab": [{"ko": "역사", "en": "history", "note": "recorded past events"}, {"ko": "충격적", "en": "shocking/sensational", "note": "adjective form of 충격 (shock)"}, {"ko": "사건", "en": "event/incident", "note": "occurrence; affair"}, {"ko": "기록되다", "en": "to be recorded/documented", "note": "passive voice of 기록하다"}], "analysis": [{"type": "grammar", "label": "~상", "exp": "Suffix meaning ''in terms of'' or ''in''. 역사상 = in history.", "example_in_sentence": "네팔 역사상"}, {"type": "grammar", "label": "~적인", "exp": "적 turns a noun into a describing word; 적인 is used before a noun. 충격 → 충격적인 사건 (a shocking event).", "example_in_sentence": "충격적인 사건"}, {"type": "grammar", "label": "~(으)로 (as)", "exp": "Here (으)로 means ''as''. 사건으로 기록되다 = to be recorded as an event.", "example_in_sentence": "사건으로 기록되고"}, {"type": "grammar", "label": "~고 있다", "exp": "progressive/continuous aspect; ongoing state or action", "example_in_sentence": "기록되고 있습니다"}]}], "version": "s1"}', vocab = '[{"ko": "마타바르싱", "en": "Matabar Singh (proper noun)", "note": "Name of Nepalese PM"}, {"ko": "조카", "en": "nephew", "note": "male sibling''s child"}, {"ko": "살해당하다", "en": "to be killed/murdered", "note": "passive voice of 살해하다"}, {"ko": "삼촌", "en": "uncle", "note": "father''s brother or mother''s brother"}, {"ko": "죽이다", "en": "to kill", "note": "active verb; past ~죽인"}, {"ko": "다른", "en": "other/different", "note": "adjective"}, {"ko": "1년", "en": "one year", "note": "duration; pure Sino-Korean number"}, {"ko": "후", "en": "after; later", "note": "temporal adverbial"}, {"ko": "총리", "en": "prime minister", "note": "head of government"}, {"ko": "역사", "en": "history", "note": "recorded past events"}, {"ko": "충격적", "en": "shocking/sensational", "note": "adjective form of 충격 (shock)"}, {"ko": "사건", "en": "event/incident", "note": "occurrence; affair"}, {"ko": "기록되다", "en": "to be recorded/documented", "note": "passive voice of 기록하다"}, {"ko": "살해하다", "en": "to kill; to murder (formal)", "note": ""}, {"ko": "되다", "en": "to become", "note": "included here because 되다 as copula/change-of-state verb is semantically key"}, {"ko": "역사상", "en": "in history; historically", "note": "noun + 상; means ''throughout history'' or ''in the history of''"}]', grammar = '{"patterns": [{"name": "~인 + noun", "level": "Intermediate", "exp": "인 (from 이다) links two nouns: ''who is''. 자신의 조카인 정 바하두르 = Jung Bahadur, his own nephew.", "ex_ko": "네팔에서 마타바르싱 총리는 자신의 조카인 정 바하두르에게 살해당했습니다.", "ex_en": "In Nepal, Prime Minister Matabar Singh was killed by his nephew Jung Bahadur."}, {"name": "~에게", "level": "Intermediate", "exp": "dative particle indicating the agent of an action in passive voice", "ex_ko": "네팔에서 마타바르싱 총리는 자신의 조카인 정 바하두르에게 살해당했습니다.", "ex_en": "In Nepal, Prime Minister Matabar Singh was killed by his nephew Jung Bahadur."}, {"name": "~당하다", "level": "Intermediate", "exp": "Added to some nouns to mean ''to suffer'' an action (passive). 살해 → 살해당하다 (to be murdered).", "ex_ko": "네팔에서 마타바르싱 총리는 자신의 조카인 정 바하두르에게 살해당했습니다.", "ex_en": "In Nepal, Prime Minister Matabar Singh was killed by his nephew Jung Bahadur."}, {"name": "~(으)ㄴ 후", "level": "Intermediate", "exp": "Means ''after doing''. 죽이다 → 죽인 후 (after killing).", "ex_ko": "정 바하두르는 삼촌을 죽인 후 다른 총리도 살해했습니다.", "ex_en": "Jung Bahadur killed his uncle and then also murdered another prime minister."}, {"name": "~도 (additive particle)", "level": "Intermediate", "exp": "also/too; marks additional action or object", "ex_ko": "정 바하두르는 삼촌을 죽인 후 다른 총리도 살해했습니다.", "ex_en": "Jung Bahadur killed his uncle and then also murdered another prime minister."}, {"name": "time + 후에", "level": "Intermediate", "exp": "Means ''later'' after a length of time. 1년 후에 = one year later.", "ex_ko": "그는 1년 후에 자신이 총리가 되었습니다.", "ex_en": "A year later, he himself became prime minister."}, {"name": "~이 되다", "level": "Intermediate", "exp": "become; copular auxiliary marking state change", "ex_ko": "그는 1년 후에 자신이 총리가 되었습니다.", "ex_en": "A year later, he himself became prime minister."}, {"name": "~상", "level": "Intermediate", "exp": "Suffix meaning ''in terms of'' or ''in''. 역사상 = in history.", "ex_ko": "이는 네팔 역사상 매우 충격적인 사건으로 기록되고 있습니다.", "ex_en": "This is being recorded as a very shocking event in Nepalese history."}, {"name": "~적인", "level": "Intermediate", "exp": "적 turns a noun into a describing word; 적인 is used before a noun. 충격 → 충격적인 사건 (a shocking event).", "ex_ko": "이는 네팔 역사상 매우 충격적인 사건으로 기록되고 있습니다.", "ex_en": "This is being recorded as a very shocking event in Nepalese history."}, {"name": "~(으)로 (as)", "level": "Intermediate", "exp": "Here (으)로 means ''as''. 사건으로 기록되다 = to be recorded as an event.", "ex_ko": "이는 네팔 역사상 매우 충격적인 사건으로 기록되고 있습니다.", "ex_en": "This is being recorded as a very shocking event in Nepalese history."}, {"name": "~고 있다", "level": "Intermediate", "exp": "progressive/continuous aspect; ongoing state or action", "ex_ko": "이는 네팔 역사상 매우 충격적인 사건으로 기록되고 있습니다.", "ex_en": "This is being recorded as a very shocking event in Nepalese history."}]}', updated_at = now() where article_id = 'mozwyfvdv1el' and md5(translation) = '9718a413b53fabedda741edcc52a4b26';
update public.article_cache set translation = '{"sentences": [{"text": "1880년대에 마가린은 판매량을 늘리기 위해 노란색으로 만들어졌어요.", "idx": 0, "translation": "In the 1880s, margarine was made yellow in order to increase sales.", "vocab": [{"ko": "마가린", "en": "margarine", "note": ""}, {"ko": "판매량", "en": "sales volume", "note": ""}, {"ko": "늘리다", "en": "increase, grow", "note": ""}], "analysis": [{"type": "grammar", "label": "~기 위해(서)", "exp": "in order to; for the purpose of", "example_in_sentence": "판매량을 늘리기 위해"}, {"type": "grammar", "label": "~아/어지다 (passive)", "exp": "Makes a verb passive. 만들다 → 만들어지다 → 만들어졌어요 (was made). 노란색으로 = (made) yellow.", "example_in_sentence": "노란색으로 만들어졌어요"}]}, {"text": "원래 마가린은 흰색이었는데, 라드와 비슷하게 생겼어요.", "idx": 1, "translation": "Originally margarine was white, and it looked similar to lard.", "vocab": [{"ko": "원래", "en": "originally", "note": ""}, {"ko": "흰색", "en": "white color", "note": ""}, {"ko": "라드", "en": "lard", "note": ""}, {"ko": "비슷하다", "en": "to be similar", "note": ""}], "analysis": [{"type": "grammar", "label": "~았/었는데", "exp": "Gives background: ''was …, and''. 흰색이다 → 흰색이었는데 (was white, and…).", "example_in_sentence": "흰색이었는데"}, {"type": "grammar", "label": "~게 생기다", "exp": "look/appear (in a certain way)", "example_in_sentence": "비슷하게 생겼어요"}]}, {"text": "유제품 업계는 마가린을 노란색으로 만드는 것을 금지하려고 로비 활동을 했어요.", "idx": 2, "translation": "The dairy industry lobbied to ban making margarine yellow.", "vocab": [{"ko": "유제품", "en": "dairy product", "note": ""}, {"ko": "업계", "en": "industry, business sector", "note": ""}, {"ko": "금지하다", "en": "ban, prohibit", "note": ""}, {"ko": "로비 활동", "en": "lobbying activity", "note": ""}], "analysis": [{"type": "grammar", "label": "~(으)려고", "exp": "Shows purpose: ''in order to''. 금지하다 → 금지하려고 (in order to ban).", "example_in_sentence": "금지하려고"}, {"type": "grammar", "label": "~는 것", "exp": "Turns a verb phrase into a noun. 만들다 → 노란색으로 만드는 것 (making it yellow); the ㄹ drops before ㄴ.", "example_in_sentence": "노란색으로 만드는 것"}]}, {"text": "그들은 이런 관행을 법으로 막으려고 노력했어요.", "idx": 3, "translation": "They made efforts to block this practice by law.", "vocab": [{"ko": "관행", "en": "practice, custom", "note": ""}, {"ko": "법", "en": "law", "note": ""}, {"ko": "막다", "en": "block, prevent", "note": ""}], "analysis": [{"type": "grammar", "label": "~(으)로 (means)", "exp": "Means ''by'' or ''with''. 법으로 막다 = to block by law.", "example_in_sentence": "법으로"}, {"type": "grammar", "label": "~(으)려고 노력하다", "exp": "Means ''to try hard to''. 막다 → 막으려고 노력했어요 (tried to block).", "example_in_sentence": "막으려고 노력했어요"}]}, {"text": "데니슨 회사는 금지 조치에 대응하는 방법을 찾았어요.", "idx": 4, "translation": "The Dennison company found a way to respond to the ban.", "vocab": [{"ko": "데니슨 회사", "en": "Dennison company", "note": "proper noun"}, {"ko": "금지 조치", "en": "ban, prohibition measure", "note": ""}, {"ko": "대응하다", "en": "respond, cope with", "note": ""}], "analysis": [{"type": "grammar", "label": "~에 대응하다", "exp": "respond to; cope with", "example_in_sentence": "금지 조치에 대응하는"}, {"type": "grammar", "label": "~는 (present modifier)", "exp": "Verb form used before a noun. 대응하다 → 대응하는 방법 (a way to respond).", "example_in_sentence": "대응하는 방법"}]}, {"text": "그들은 소비자들이 직접 섞을 수 있는 노란색 염료 캡슐과 함께 마가린을 판매했어요.", "idx": 5, "translation": "They sold margarine together with yellow dye capsules that consumers could mix directly.", "vocab": [{"ko": "소비자", "en": "consumer", "note": ""}, {"ko": "직접", "en": "directly, in person", "note": ""}, {"ko": "섞다", "en": "to mix", "note": ""}, {"ko": "염료", "en": "dye, coloring agent", "note": ""}, {"ko": "캡슐", "en": "capsule", "note": ""}], "analysis": [{"type": "grammar", "label": "~ㄹ/을 수 있는", "exp": "can/able to (modifying)", "example_in_sentence": "섞을 수 있는"}, {"type": "grammar", "label": "~과/와 함께", "exp": "together with; along with", "example_in_sentence": "캡슐과 함께"}]}, {"text": "이렇게 해서 소비자들은 집에서 흰색 마가린에 노란 염료를 넣어 색을 바꿀 수 있었어요.", "idx": 6, "translation": "In this way, consumers were able to change the color by putting yellow dye into white margarine at home.", "vocab": [{"ko": "이렇게", "en": "in this way, like this", "note": ""}, {"ko": "집", "en": "home, house", "note": ""}, {"ko": "색", "en": "color", "note": ""}], "analysis": [{"type": "grammar", "label": "~ㄹ/을 수 있었다", "exp": "was able to; could (past)", "example_in_sentence": "바꿀 수 있었어요"}, {"type": "grammar", "label": "~에 ~을/를 넣다", "exp": "put/insert into", "example_in_sentence": "마가린에 노란 염료를 넣어"}, {"type": "grammar", "label": "~아/어(서)", "exp": "Links actions in order: ''and (then)''. 넣다 → 넣어 (put in, and…). 서 is often dropped in writing.", "example_in_sentence": "넣어"}]}, {"text": "법적 제재를 피하면서도 노란색 마가린을 만들 수 있는 방법이었어요.", "idx": 7, "translation": "It was a way to make yellow margarine while avoiding legal penalties.", "vocab": [{"ko": "법적", "en": "legal", "note": ""}, {"ko": "제재", "en": "sanction, penalty", "note": ""}, {"ko": "피하다", "en": "avoid, evade", "note": ""}], "analysis": [{"type": "grammar", "label": "~(으)면서도", "exp": "Means ''while (still)'': doing one thing and also another. 피하다 → 피하면서도 (while still avoiding).", "example_in_sentence": "피하면서도"}, {"type": "grammar", "label": "~ㄹ 수 있다", "exp": "can/able to", "example_in_sentence": "만들 수 있는"}]}], "version": "s1"}', vocab = '[{"ko": "마가린", "en": "margarine", "note": ""}, {"ko": "판매량", "en": "sales volume", "note": ""}, {"ko": "늘리다", "en": "increase, grow", "note": ""}, {"ko": "원래", "en": "originally", "note": ""}, {"ko": "흰색", "en": "white color", "note": ""}, {"ko": "라드", "en": "lard", "note": ""}, {"ko": "비슷하다", "en": "to be similar", "note": ""}, {"ko": "유제품", "en": "dairy product", "note": ""}, {"ko": "업계", "en": "industry, business sector", "note": ""}, {"ko": "금지하다", "en": "ban, prohibit", "note": ""}, {"ko": "로비 활동", "en": "lobbying activity", "note": ""}, {"ko": "관행", "en": "practice, custom", "note": ""}, {"ko": "법", "en": "law", "note": ""}, {"ko": "막다", "en": "block, prevent", "note": ""}, {"ko": "데니슨 회사", "en": "Dennison company", "note": "proper noun"}, {"ko": "금지 조치", "en": "ban, prohibition measure", "note": ""}, {"ko": "대응하다", "en": "respond, cope with", "note": ""}, {"ko": "소비자", "en": "consumer", "note": ""}, {"ko": "직접", "en": "directly, in person", "note": ""}, {"ko": "섞다", "en": "to mix", "note": ""}, {"ko": "염료", "en": "dye, coloring agent", "note": ""}, {"ko": "캡슐", "en": "capsule", "note": ""}, {"ko": "이렇게", "en": "in this way, like this", "note": ""}, {"ko": "집", "en": "home, house", "note": ""}, {"ko": "색", "en": "color", "note": ""}, {"ko": "법적", "en": "legal", "note": ""}, {"ko": "제재", "en": "sanction, penalty", "note": ""}, {"ko": "피하다", "en": "avoid, evade", "note": ""}, {"ko": "노란색", "en": "yellow color", "note": ""}, {"ko": "로비", "en": "lobby", "note": ""}, {"ko": "노력하다", "en": "to make effort", "note": ""}, {"ko": "금지", "en": "ban / prohibition", "note": ""}, {"ko": "조치", "en": "measure / action", "note": ""}, {"ko": "방법", "en": "method / way", "note": ""}, {"ko": "바꾸다", "en": "to change", "note": ""}, {"ko": "넣다", "en": "to put / to add", "note": ""}]', grammar = '{"patterns": [{"name": "~기 위해(서)", "level": "Intermediate", "exp": "in order to; for the purpose of", "ex_ko": "1880년대에 마가린은 판매량을 늘리기 위해 노란색으로 만들어졌어요.", "ex_en": "In the 1880s, margarine was made yellow in order to increase sales."}, {"name": "~아/어지다 (passive)", "level": "Intermediate", "exp": "Makes a verb passive. 만들다 → 만들어지다 → 만들어졌어요 (was made). 노란색으로 = (made) yellow.", "ex_ko": "1880년대에 마가린은 판매량을 늘리기 위해 노란색으로 만들어졌어요.", "ex_en": "In the 1880s, margarine was made yellow in order to increase sales."}, {"name": "~았/었는데", "level": "Intermediate", "exp": "Gives background: ''was …, and''. 흰색이다 → 흰색이었는데 (was white, and…).", "ex_ko": "원래 마가린은 흰색이었는데, 라드와 비슷하게 생겼어요.", "ex_en": "Originally margarine was white, and it looked similar to lard."}, {"name": "~게 생기다", "level": "Intermediate", "exp": "look/appear (in a certain way)", "ex_ko": "원래 마가린은 흰색이었는데, 라드와 비슷하게 생겼어요.", "ex_en": "Originally margarine was white, and it looked similar to lard."}, {"name": "~(으)려고", "level": "Intermediate", "exp": "Shows purpose: ''in order to''. 금지하다 → 금지하려고 (in order to ban).", "ex_ko": "유제품 업계는 마가린을 노란색으로 만드는 것을 금지하려고 로비 활동을 했어요.", "ex_en": "The dairy industry lobbied to ban making margarine yellow."}, {"name": "~는 것", "level": "Intermediate", "exp": "Turns a verb phrase into a noun. 만들다 → 노란색으로 만드는 것 (making it yellow); the ㄹ drops before ㄴ.", "ex_ko": "유제품 업계는 마가린을 노란색으로 만드는 것을 금지하려고 로비 활동을 했어요.", "ex_en": "The dairy industry lobbied to ban making margarine yellow."}, {"name": "~(으)로 (means)", "level": "Intermediate", "exp": "Means ''by'' or ''with''. 법으로 막다 = to block by law.", "ex_ko": "그들은 이런 관행을 법으로 막으려고 노력했어요.", "ex_en": "They made efforts to block this practice by law."}, {"name": "~(으)려고 노력하다", "level": "Intermediate", "exp": "Means ''to try hard to''. 막다 → 막으려고 노력했어요 (tried to block).", "ex_ko": "그들은 이런 관행을 법으로 막으려고 노력했어요.", "ex_en": "They made efforts to block this practice by law."}, {"name": "~에 대응하다", "level": "Intermediate", "exp": "respond to; cope with", "ex_ko": "데니슨 회사는 금지 조치에 대응하는 방법을 찾았어요.", "ex_en": "The Dennison company found a way to respond to the ban."}, {"name": "~는 (present modifier)", "level": "Intermediate", "exp": "Verb form used before a noun. 대응하다 → 대응하는 방법 (a way to respond).", "ex_ko": "데니슨 회사는 금지 조치에 대응하는 방법을 찾았어요.", "ex_en": "The Dennison company found a way to respond to the ban."}, {"name": "~ㄹ/을 수 있는", "level": "Intermediate", "exp": "can/able to (modifying)", "ex_ko": "그들은 소비자들이 직접 섞을 수 있는 노란색 염료 캡슐과 함께 마가린을 판매했어요.", "ex_en": "They sold margarine together with yellow dye capsules that consumers could mix directly."}, {"name": "~과/와 함께", "level": "Intermediate", "exp": "together with; along with", "ex_ko": "그들은 소비자들이 직접 섞을 수 있는 노란색 염료 캡슐과 함께 마가린을 판매했어요.", "ex_en": "They sold margarine together with yellow dye capsules that consumers could mix directly."}, {"name": "~ㄹ/을 수 있었다", "level": "Intermediate", "exp": "was able to; could (past)", "ex_ko": "이렇게 해서 소비자들은 집에서 흰색 마가린에 노란 염료를 넣어 색을 바꿀 수 있었어요.", "ex_en": "In this way, consumers were able to change the color by putting yellow dye into white margarine at home."}, {"name": "~에 ~을/를 넣다", "level": "Intermediate", "exp": "put/insert into", "ex_ko": "이렇게 해서 소비자들은 집에서 흰색 마가린에 노란 염료를 넣어 색을 바꿀 수 있었어요.", "ex_en": "In this way, consumers were able to change the color by putting yellow dye into white margarine at home."}, {"name": "~아/어(서)", "level": "Intermediate", "exp": "Links actions in order: ''and (then)''. 넣다 → 넣어 (put in, and…). 서 is often dropped in writing.", "ex_ko": "이렇게 해서 소비자들은 집에서 흰색 마가린에 노란 염료를 넣어 색을 바꿀 수 있었어요.", "ex_en": "In this way, consumers were able to change the color by putting yellow dye into white margarine at home."}]}', updated_at = now() where article_id = 'mozyljjpwi32' and md5(translation) = '6054de7d060e8f513b8ce49215fcd660';
update public.article_cache set translation = '{"texts": ["Baltimore, Maryland was the second city in the United States to achieve a population of 100,000. Until the 1990 census, this city was one of the top 10 most populous cities in the United States.", "Baltimore''s population reached its peak in the 1950 census. At that time, Baltimore had 950,000 residents living in the city.", "Baltimore was long considered one of the major cities in the United States. However, after 1990, it fell out of the top 10 most populous cities."], "sentences": [{"text": "미국 메릴랜드주 볼티모어는 미국에서 두 번째로 인구 10만 명을 달성한 도시였어요.", "translation": "Baltimore, Maryland was the second city in the United States to achieve a population of 100,000.", "vocab": [{"ko": "메릴랜드주", "en": "Maryland (state)", "note": ""}, {"ko": "달성하다", "en": "to achieve / to attain", "note": ""}, {"ko": "인구", "en": "population", "note": ""}], "analysis": [{"type": "grammar", "label": "~번째로", "exp": "Means ''as the (second, third…)''. 두 번째로 = as the second (city).", "example_in_sentence": "두 번째로"}]}, {"text": "이 도시는 1990년 인구 조사까지 미국 인구 상위 10대 도시 중 하나였습니다.", "translation": "Until the 1990 census, this city was one of the top 10 most populous cities in the United States.", "vocab": [{"ko": "인구 조사", "en": "census", "note": ""}, {"ko": "상위", "en": "top / upper rank", "note": ""}], "analysis": [{"type": "grammar", "label": "~까지 (until)", "exp": "Temporal/spatial limit particle meaning ''up to / until / as far as''. Marks 1990년 인구 조사 as the endpoint of the period during which the city ranked in the top 10.", "example_in_sentence": "1990년 인구 조사까지"}, {"type": "expression", "label": "~ 중 하나", "exp": "Means ''one of''. 상위 10대 도시 중 하나 = one of the top 10 cities.", "example_in_sentence": "도시 중 하나였습니다"}]}, {"text": "볼티모어의 인구는 1950년 인구 조사에서 최고치를 기록했어요.", "translation": "Baltimore''s population reached its peak in the 1950 census.", "vocab": [{"ko": "최고치", "en": "peak / highest point / maximum", "note": ""}, {"ko": "기록하다", "en": "to record / to set (a record)", "note": ""}], "analysis": [{"type": "expression", "label": "최고치를 기록하다", "exp": "Means ''to hit a peak'' or ''reach a record high''. 기록하다 → 기록했어요.", "example_in_sentence": "최고치를 기록했어요"}]}, {"text": "당시 볼티모어에는 95만 명의 주민이 살고 있었습니다.", "translation": "At that time, Baltimore had 950,000 residents living in the city.", "vocab": [{"ko": "당시", "en": "at that time / then", "note": ""}, {"ko": "주민", "en": "resident / inhabitant", "note": ""}], "analysis": [{"type": "grammar", "label": "~고 있다", "exp": "Describes an ongoing state in the past. 살다 → 살고 있었습니다 (were living).", "example_in_sentence": "살고 있었습니다"}]}, {"text": "볼티모어는 오랫동안 미국의 주요 도시 중 하나로 여겨졌어요.", "translation": "Baltimore was long considered one of the major cities in the United States.", "vocab": [{"ko": "오랫동안", "en": "for a long time / for a long period", "note": ""}, {"ko": "주요", "en": "major / main / key", "note": ""}, {"ko": "여기다", "en": "to regard / to consider / to view as", "note": ""}], "analysis": [{"type": "expression", "label": "~ 중 하나로", "exp": "Means ''as one of''. 주요 도시 중 하나로 여겨지다 = to be seen as one of the major cities.", "example_in_sentence": "도시 중 하나로"}, {"type": "grammar", "label": "~아/어지다 (passive)", "exp": "Makes a verb passive. 여기다 (to regard) → 여겨지다 (to be regarded) → 여겨졌어요.", "example_in_sentence": "여겨졌어요"}]}, {"text": "하지만 1990년 이후에는 인구 상위 10대 도시에서 벗어나게 되었습니다.", "translation": "However, after 1990, it fell out of the top 10 most populous cities.", "vocab": [{"ko": "이후", "en": "after / afterwards / subsequent to", "note": ""}, {"ko": "벗어나다", "en": "to come out / to escape / to fall out of", "note": ""}], "analysis": [{"type": "grammar", "label": "~게 되다", "exp": "Shows a change that happened: ''came to; ended up''. 벗어나다 → 벗어나게 되었습니다 (ended up falling out).", "example_in_sentence": "벗어나게 되었습니다"}, {"type": "grammar", "label": "~에서 벗어나다", "exp": "Means ''to get out of'' or ''fall out of''. 10대 도시에서 벗어나다 = to drop out of the top 10.", "example_in_sentence": "도시에서 벗어나게"}]}], "vers