update public.article_cache set translation = '{"texts": ["It has been discovered that cold weather affects our body''s immunity. In particular, the immune function in the nose reacts sensitively to temperature changes. According to research, when the temperature of nasal tissue drops by just 5 degrees, the immune response decreases significantly. To be precise, the immune response decreases to almost half its normal level. This weakening of immunity makes it easier to get infected with viruses. This is because cold temperatures reduce the nose''s defensive ability. This explains why we catch colds and flu more frequently during winter. When cold air enters the nose directly, it weakens the immune system.", "Korean Teacher Shortage Becomes Serious, School Classes Disrupted", "What is an \"anxiety bag\"? A Popular Trend", "The United States and China Resume Talks Over Trade Issues", "\"Talking Pig\" Becomes SNS Star", "Apple Greatly Improves iPhone Speed with New AI Chip"], "sentences": [{"text": "추운 날씨가 우리 몸의 면역력에 영향을 준다는 사실이 밝혀졌어요.", "translation": "It has been revealed that cold weather affects the immune system of our bodies.", "vocab": [{"ko": "춥다", "en": "to be cold"}, {"ko": "면역력", "en": "immunity; immune system"}, {"ko": "영향을 주다", "en": "to affect; to have an impact on"}, {"ko": "밝혀지다", "en": "to be revealed; to come to light"}], "analysis": [{"type": "grammar", "label": "~ㄴ/는다는 사실", "exp": "Links a statement to 사실 (fact): ''the fact that…''. 주다 → 준다는 사실 (the fact that it affects).", "example_in_sentence": "영향을 준다는 사실"}, {"type": "expression", "label": "~에 영향을 주다", "exp": "Collocation meaning ''to affect/influence (someone/something)''. Shows causal relationship between agent and target.", "example_in_sentence": "면역력에 영향을 준다"}]}, {"text": "특히 코 부분의 면역 기능이 온도 변화에 민감하게 반응한다고 해요.", "translation": "Particularly, the immune function of the nasal area responds sensitively to temperature changes, they say.", "vocab": [{"ko": "특히", "en": "especially; particularly"}, {"ko": "민감하다", "en": "to be sensitive"}, {"ko": "반응하다", "en": "to react; to respond"}], "analysis": [{"type": "grammar", "label": "~게", "exp": "Turns an adjective into an adverb. 민감하다 → 민감하게 (sensitively).", "example_in_sentence": "민감하게"}, {"type": "grammar", "label": "~ㄴ/는다고 하다", "exp": "Reports what others say: ''they say that…''. 반응하다 → 반응한다고 해요.", "example_in_sentence": "반응한다고 해요"}]}, {"text": "연구에 따르면 코 조직의 온도가 단 5도만 떨어져도 면역 반응이 크게 줄어든다고 해요.", "translation": "According to research, even if the temperature of nasal tissue drops only by 5 degrees, the immune response greatly decreases, they say.", "vocab": [{"ko": "연구", "en": "research; study"}, {"ko": "조직", "en": "tissue"}, {"ko": "떨어지다", "en": "to fall; to drop; to decrease"}, {"ko": "줄어들다", "en": "to decrease; to diminish"}], "analysis": [{"type": "expression", "label": "~에 따르면", "exp": "Phrase meaning ''according to'' or ''based on''. Marks the source of information or basis for statement.", "example_in_sentence": "연구에 따르면"}, {"type": "grammar", "label": "~아/어도", "exp": "Concessive connective suffix meaning ''even if; even though''. Indicates that the condition does not prevent the result. 떨어지다 → 떨어져도.", "example_in_sentence": "떨어져도"}, {"type": "grammar", "label": "~ㄴ다고 해요", "exp": "Reportative expression indicating indirect quotation or secondhand information. Present tense form. 줄어들다 → 줄어든다고.", "example_in_sentence": "줄어든다고 해요"}]}, {"text": "정확히는 면역 반응이 거의 절반 수준까지 감소한다고 합니다.", "translation": "To be precise, the immune response decreases to almost half the level, it is said.", "vocab": [{"ko": "정확히", "en": "precisely; exactly"}, {"ko": "절반", "en": "half"}, {"ko": "감소하다", "en": "to decrease; to reduce"}], "analysis": [{"type": "grammar", "label": "~ㄴ다고 합니다", "exp": "Formal reportative/hearsay form in polite speech. Conveys information from external source or general knowledge. 감소하다 → 감소한다고.", "example_in_sentence": "감소한다고 합니다"}, {"type": "expression", "label": "~까지", "exp": "Particle indicating the extent or limit of a degree/level. Often paired with 수준 (level) to show how far something reaches.", "example_in_sentence": "수준까지"}]}, {"text": "이런 면역력 약화는 바이러스에 더 쉽게 감염될 수 있게 만들어요.", "translation": "This weakened immunity makes it easier to get infected with viruses.", "vocab": [{"ko": "약화", "en": "weakening; decline"}, {"ko": "바이러스", "en": "virus"}, {"ko": "감염되다", "en": "to be infected"}], "analysis": [{"type": "grammar", "label": "~(으)ㄹ 수 있다", "exp": "Means ''can'' or ''may''. 감염되다 → 감염될 수 있다 (can get infected).", "example_in_sentence": "감염될 수 있게"}, {"type": "grammar", "label": "~게 만들다", "exp": "Means ''to make something happen''. 감염될 수 있다 → 감염될 수 있게 만들어요 (makes it possible to get infected).", "example_in_sentence": "감염될 수 있게 만들어요"}]}, {"text": "추운 온도가 코의 방어 능력을 떨어뜨리기 때문이에요.", "translation": "It is because cold temperature lowers the defense ability of the nose.", "vocab": [{"ko": "방어", "en": "defense; protection"}, {"ko": "능력", "en": "ability; capacity"}, {"ko": "떨어뜨리다", "en": "to lower; to reduce; to weaken"}], "analysis": [{"type": "grammar", "label": "~기 때문이다", "exp": "Causal construction meaning ''because; it is because.'' The ~기 form nominalizes the preceding verb/adjective, and 때문이다 marks it as the reason/cause. 떨어뜨리다 → 떨어뜨리기.", "example_in_sentence": "떨어뜨리기 때문이에요"}]}, {"text": "그래서 겨울철에 감기나 독감에 더 자주 걸리는 이유를 설명할 수 있어요.", "translation": "Therefore, we can explain the reason why people catch colds or flu more frequently in winter.", "vocab": [{"ko": "겨울철", "en": "winter season"}, {"ko": "감기", "en": "cold (illness)"}, {"ko": "독감", "en": "flu; influenza"}, {"ko": "걸리다", "en": "to catch (an illness)"}], "analysis": [{"type": "grammar", "label": "~는 이유", "exp": "Nominalizing construction using present/habitual modifier ~는 to create a noun phrase meaning ''the reason why (something happens).'' 걸리다 → 걸리는.", "example_in_sentence": "걸리는 이유"}, {"type": "grammar", "label": "~(으)ㄹ 수 있다", "exp": "Means ''can''. 설명하다 → 설명할 수 있어요 (can explain).", "example_in_sentence": "설명할 수 있어요"}]}, {"text": "차가운 공기가 직접 코로 들어가면서 면역 시스템을 약하게 만든다고 해요.", "translation": "As cold air enters the nose directly, it makes the immune system weak, they say.", "vocab": [{"ko": "차갑다", "en": "to be cold; chilly"}, {"ko": "공기", "en": "air"}, {"ko": "들어가다", "en": "to enter; to go in"}, {"ko": "시스템", "en": "system"}], "analysis": [{"type": "grammar", "label": "~(으)면서", "exp": "Means ''as'' or ''while''. 들어가다 → 들어가면서 (as it goes in).", "example_in_sentence": "들어가면서"}, {"type": "grammar", "label": "~ㄴ다고 해요", "exp": "Reportative/hearsay form in informal speech indicating information from external source or general knowledge. Present tense. 만들다 → 만든다고.", "example_in_sentence": "만든다고 해요"}]}], "version": "s6"}', vocab = '[{"ko": "춥다", "en": "to be cold", "note": ""}, {"ko": "면역력", "en": "immunity; immune system", "note": ""}, {"ko": "영향을 주다", "en": "to affect; to have an impact on", "note": ""}, {"ko": "밝혀지다", "en": "to be revealed; to come to light", "note": ""}, {"ko": "특히", "en": "especially; particularly", "note": ""}, {"ko": "민감하다", "en": "to be sensitive", "note": ""}, {"ko": "반응하다", "en": "to react; to respond", "note": ""}, {"ko": "연구", "en": "research; study", "note": ""}, {"ko": "조직", "en": "tissue", "note": ""}, {"ko": "떨어지다", "en": "to fall; to drop; to decrease", "note": ""}, {"ko": "줄어들다", "en": "to decrease; to diminish", "note": ""}, {"ko": "정확히", "en": "precisely; exactly", "note": ""}, {"ko": "절반", "en": "half", "note": ""}, {"ko": "감소하다", "en": "to decrease; to reduce", "note": ""}, {"ko": "약화", "en": "weakening; decline", "note": ""}, {"ko": "바이러스", "en": "virus", "note": ""}, {"ko": "감염되다", "en": "to be infected", "note": ""}, {"ko": "방어", "en": "defense; protection", "note": ""}, {"ko": "능력", "en": "ability; capacity", "note": ""}, {"ko": "떨어뜨리다", "en": "to lower; to reduce; to weaken", "note": ""}, {"ko": "겨울철", "en": "winter season", "note": ""}, {"ko": "감기", "en": "cold (illness)", "note": ""}, {"ko": "독감", "en": "flu; influenza", "note": ""}, {"ko": "걸리다", "en": "to catch (an illness)", "note": ""}, {"ko": "차갑다", "en": "to be cold; chilly", "note": ""}, {"ko": "공기", "en": "air", "note": ""}, {"ko": "들어가다", "en": "to enter; to go in", "note": ""}, {"ko": "시스템", "en": "system", "note": ""}, {"ko": "기능", "en": "function", "note": "capability or role"}, {"ko": "거의", "en": "nearly/almost", "note": "approximately"}, {"ko": "만들다", "en": "to make/cause", "note": "to create or cause"}, {"ko": "직접", "en": "directly", "note": "without intermediary"}]', grammar = '{"patterns": [{"name": "~ㄴ/는다는 사실", "level": "Intermediate", "exp": "Links a statement to 사실 (fact): ''the fact that…''. 주다 → 준다는 사실 (the fact that it affects).", "ex_ko": "추운 날씨가 우리 몸의 면역력에 영향을 준다는 사실이 밝혀졌어요.", "ex_en": "It has been revealed that cold weather affects the immune system of our bodies."}, {"name": "~게", "level": "Intermediate", "exp": "Turns an adjective into an adverb. 민감하다 → 민감하게 (sensitively).", "ex_ko": "특히 코 부분의 면역 기능이 온도 변화에 민감하게 반응한다고 해요.", "ex_en": "Particularly, the immune function of the nasal area responds sensitively to temperature changes, they say."}, {"name": "~ㄴ/는다고 하다", "level": "Intermediate", "exp": "Reports what others say: ''they say that…''. 반응하다 → 반응한다고 해요.", "ex_ko": "특히 코 부분의 면역 기능이 온도 변화에 민감하게 반응한다고 해요.", "ex_en": "Particularly, the immune function of the nasal area responds sensitively to temperature changes, they say."}, {"name": "~아/어도", "level": "Intermediate", "exp": "Concessive connective suffix meaning ''even if; even though''. Indicates that the condition does not prevent the result. 떨어지다 → 떨어져도.", "ex_ko": "연구에 따르면 코 조직의 온도가 단 5도만 떨어져도 면역 반응이 크게 줄어든다고 해요.", "ex_en": "According to research, even if the temperature of nasal tissue drops only by 5 degrees, the immune response greatly decreases, they say."}, {"name": "~ㄴ다고 해요", "level": "Intermediate", "exp": "Reportative/hearsay form in informal speech indicating information from external source or general knowledge. Present tense. 만들다 → 만든다고.", "ex_ko": "연구에 따르면 코 조직의 온도가 단 5도만 떨어져도 면역 반응이 크게 줄어든다고 해요.", "ex_en": "According to research, even if the temperature of nasal tissue drops only by 5 degrees, the immune response greatly decreases, they say."}, {"name": "~ㄴ다고 합니다", "level": "Intermediate", "exp": "Formal reportative/hearsay form in polite speech. Conveys information from external source or general knowledge. 감소하다 → 감소한다고.", "ex_ko": "정확히는 면역 반응이 거의 절반 수준까지 감소한다고 합니다.", "ex_en": "To be precise, the immune response decreases to almost half the level, it is said."}, {"name": "~(으)ㄹ 수 있다", "level": "Intermediate", "exp": "Means ''can'' or ''may''. 감염되다 → 감염될 수 있다 (can get infected).", "ex_ko": "이런 면역력 약화는 바이러스에 더 쉽게 감염될 수 있게 만들어요.", "ex_en": "This weakened immunity makes it easier to get infected with viruses."}, {"name": "~게 만들다", "level": "Intermediate", "exp": "Means ''to make something happen''. 감염될 수 있다 → 감염될 수 있게 만들어요 (makes it possible to get infected).", "ex_ko": "이런 면역력 약화는 바이러스에 더 쉽게 감염될 수 있게 만들어요.", "ex_en": "This weakened immunity makes it easier to get infected with viruses."}, {"name": "~기 때문이다", "level": "Intermediate", "exp": "Causal construction meaning ''because; it is because.'' The ~기 form nominalizes the preceding verb/adjective, and 때문이다 marks it as the reason/cause. 떨어뜨리다 → 떨어뜨리기.", "ex_ko": "추운 온도가 코의 방어 능력을 떨어뜨리기 때문이에요.", "ex_en": "It is because cold temperature lowers the defense ability of the nose."}, {"name": "~는 이유", "level": "Intermediate", "exp": "Nominalizing construction using present/habitual modifier ~는 to create a noun phrase meaning ''the reason why (something happens).'' 걸리다 → 걸리는.", "ex_ko": "그래서 겨울철에 감기나 독감에 더 자주 걸리는 이유를 설명할 수 있어요.", "ex_en": "Therefore, we can explain the reason why people catch colds or flu more frequently in winter."}, {"name": "~(으)면서", "level": "Intermediate", "exp": "Means ''as'' or ''while''. 들어가다 → 들어가면서 (as it goes in).", "ex_ko": "차가운 공기가 직접 코로 들어가면서 면역 시스템을 약하게 만든다고 해요.", "ex_en": "As cold air enters the nose directly, it makes the immune system weak, they say."}]}', updated_at = now() where article_id = 'mozz32yrjueo' and md5(translation) = '87f46b21208929e722208c96a3e122dd';
update public.article_cache set translation = '{"texts": ["The U.S. Capitol building was originally designed to house the remains of George Washington. This plan was a special way of expressing respect for the first president. Congress specially designed a viewing room where visitors could look down upon Washington''s tomb. This viewing room was created as a space where people could pay respects to the president''s tomb by looking down from above.\n\nHowever, Washington''s will stated that he should be buried at Mount Vernon. He wanted to rest eternally on his homeland soil.\n\nEventually, following Washington''s wishes, the plan for a tomb in the Capitol was abandoned. Today, George Washington rests at Mount Vernon, exactly as he desired.", "Korean teacher shortage crisis worsens, disrupting school classes", "What is an ''anxiety bag''? A popular trend", "The US and China resume talks over trade issues", "\"Talking pig\" becomes an SNS star", "''Nothing maxing'' trend spreads—doing absolutely nothing"], "sentences": [{"text": "미국 국회의사당 건물은 원래 조지 워싱턴의 유해를 보관하기 위해 설계되었습니다.", "translation": "The U.S. Capitol building was originally designed to hold George Washington''s remains.", "vocab": [{"ko": "유해", "en": "remains; mortal remains"}, {"ko": "보관하다", "en": "to keep; to store"}, {"ko": "설계되다", "en": "to be designed"}], "analysis": [{"type": "grammar", "label": "~기 위해", "exp": "Purpose/goal marker. Connects a verb stem (보관하다 → 보관하기) with purposive meaning ''in order to; for the purpose of''.", "example_in_sentence": "보관하기 위해"}]}, {"text": "이 계획은 초대 대통령에 대한 존경을 표현하는 특별한 방법이었습니다.", "translation": "This plan was a special way of expressing respect for the first president.", "vocab": [{"ko": "초대", "en": "first; inaugural"}, {"ko": "존경", "en": "respect; reverence"}, {"ko": "표현하다", "en": "to express"}], "analysis": [{"type": "expression", "label": "~ 에 대한", "exp": "Relational/attributive construction marking the target/object of an action or emotion. ''toward; regarding; for''.", "example_in_sentence": "대통령에 대한"}, {"type": "grammar", "label": "~는 (present modifier)", "exp": "Verb form used before a noun. 표현하다 → 표현하는 (expressing). 표현하는 특별한 방법 = a special way of expressing.", "example_in_sentence": "표현하는"}]}, {"text": "국회는 방문객들이 워싱턴의 무덤을 내려다볼 수 있는 관람실을 특별히 설계했습니다.", "translation": "Congress specially designed a viewing room where visitors could look down at Washington''s tomb.", "vocab": [{"ko": "방문객", "en": "visitor"}, {"ko": "내려다보다", "en": "to look down at; to overlook"}, {"ko": "관람실", "en": "viewing room; observation room"}], "analysis": [{"type": "grammar", "label": "~ㄹ 수 있다", "exp": "Ability/possibility modal. Attaches to verb stem (내려다보다 → 내려다볼) to express ''be able to; can''.", "example_in_sentence": "내려다볼 수 있는"}]}, {"text": "이 관람실은 사람들이 위에서 아래를 보며 대통령의 무덤을 참배할 수 있도록 만들어진 공간이었습니다.", "translation": "This viewing room was a space created so that people could pay respects to the president''s tomb while looking down from above.", "vocab": [{"ko": "참배하다", "en": "to pay respects; to visit and worship"}, {"ko": "만들어지다", "en": "to be made; to be created"}], "analysis": [{"type": "grammar", "label": "~도록", "exp": "Purpose/result marker; expresses ''so that; in order that''. Often used with potential forms (참배할 수 있도록).", "example_in_sentence": "참배할 수 있도록"}, {"type": "grammar", "label": "~아/어진 (passive modifier)", "exp": "Passive 만들어지다 used before a noun. 만들어진 공간 = a space that was made.", "example_in_sentence": "만들어진 공간"}]}, {"text": "하지만 워싱턴의 유언장에는 자신을 마운트 버넌에 묻어달라는 내용이 적혀 있었습니다.", "translation": "However, Washington''s will contained a request to be buried at Mount Vernon.", "vocab": [{"ko": "유언장", "en": "will; testament"}, {"ko": "묻다", "en": "to bury"}, {"ko": "적혀 있다", "en": "to be written"}], "analysis": [{"type": "grammar", "label": "~아/어 달라는", "exp": "Reports a request: ''asking (someone) to do''. 묻다 → 묻어 달라는 내용 (a request to bury him).", "example_in_sentence": "묻어달라는 내용"}, {"type": "grammar", "label": "~어 있다", "exp": "Stative auxiliary. Marks completed state or condition: ''be in a state of; have been written''.", "example_in_sentence": "적혀 있었습니다"}]}, {"text": "그는 자신의 고향 땅에서 영원히 쉬고 싶어 했던 것입니다.", "translation": "He wanted to rest eternally in his homeland.", "vocab": [{"ko": "영원히", "en": "eternally; forever"}, {"ko": "쉬다", "en": "to rest"}], "analysis": [{"type": "grammar", "label": "~고 싶어 하다", "exp": "Used for what someone else wants. 쉬다 → 쉬고 싶어 하다 (he wanted to rest).", "example_in_sentence": "쉬고 싶어 했던"}, {"type": "grammar", "label": "~았/었던 것이다", "exp": "Explains the reason behind something in the past: ''it was that…''. 싶어 하다 → 싶어 했던 것입니다.", "example_in_sentence": "싶어 했던 것입니다"}]}, {"text": "결국 워싱턴의 유언에 따라 국회의사당 무덤 계획은 중단되었습니다.", "translation": "Ultimately, the Capitol tomb plan was abandoned in accordance with Washington''s will.", "vocab": [{"ko": "결국", "en": "in the end; ultimately"}, {"ko": "중단되다", "en": "to be discontinued; to be abandoned"}], "analysis": [{"type": "expression", "label": "~ 에 따라", "exp": "Sequential/causal relational marker. Means ''according to; in accordance with; following''.", "example_in_sentence": "유언에 따라"}]}, {"text": "오늘날 조지 워싱턴은 그가 원했던 대로 마운트 버넌에 잠들어 있습니다.", "translation": "Today George Washington rests at Mount Vernon just as he wished.", "vocab": [{"ko": "원하다", "en": "to want; to wish"}, {"ko": "잠들다", "en": "to fall asleep; to rest (euphemism for death)"}], "analysis": [{"type": "grammar", "label": "~았/었던 대로", "exp": "Means ''just as (someone) did''. 원하다 → 원했던 대로 (just as he wished).", "example_in_sentence": "원했던 대로"}, {"type": "grammar", "label": "~어 있다", "exp": "Stative auxiliary expressing continued state: ''be in a state of; be resting''.", "example_in_sentence": "잠들어 있습니다"}]}], "version": "s6"}', vocab = '[{"ko": "유해", "en": "remains; mortal remains", "note": ""}, {"ko": "보관하다", "en": "to keep; to store", "note": ""}, {"ko": "설계되다", "en": "to be designed", "note": ""}, {"ko": "초대", "en": "first; inaugural", "note": ""}, {"ko": "존경", "en": "respect; reverence", "note": ""}, {"ko": "표현하다", "en": "to express", "note": ""}, {"ko": "방문객", "en": "visitor", "note": ""}, {"ko": "내려다보다", "en": "to look down at; to overlook", "note": ""}, {"ko": "관람실", "en": "viewing room; observation room", "note": ""}, {"ko": "참배하다", "en": "to pay respects; to visit and worship", "note": ""}, {"ko": "만들어지다", "en": "to be made; to be created", "note": ""}, {"ko": "유언장", "en": "will; testament", "note": ""}, {"ko": "묻다", "en": "to bury", "note": ""}, {"ko": "적혀 있다", "en": "to be written", "note": ""}, {"ko": "영원히", "en": "eternally; forever", "note": ""}, {"ko": "쉬다", "en": "to rest", "note": ""}, {"ko": "결국", "en": "in the end; ultimately", "note": ""}, {"ko": "중단되다", "en": "to be discontinued; to be abandoned", "note": ""}, {"ko": "원하다", "en": "to want; to wish", "note": ""}, {"ko": "잠들다", "en": "to fall asleep; to rest (euphemism for death)", "note": ""}, {"ko": "국회의사당", "en": "capitol building", "note": "government legislative building"}, {"ko": "계획", "en": "plan", "note": "scheme or project"}, {"ko": "국회", "en": "congress", "note": "legislative assembly"}, {"ko": "무덤", "en": "tomb, grave", "note": "burial site"}, {"ko": "공간", "en": "space", "note": "area or room"}, {"ko": "내용", "en": "content, contents", "note": "substance or details"}, {"ko": "적히다", "en": "to be written", "note": "passive form of ''to write''"}, {"ko": "고향", "en": "hometown, homeland", "note": "place of birth or origin"}, {"ko": "유언", "en": "will, last words", "note": "final wishes of deceased"}, {"ko": "중단하다", "en": "to stop, to suspend", "note": "to halt or discontinue"}, {"ko": "오늘날", "en": "nowadays, today", "note": "in the present time"}]', grammar = '{"patterns": [{"name": "~기 위해", "level": "Intermediate", "exp": "Purpose/goal marker. Connects a verb stem (보관하다 → 보관하기) with purposive meaning ''in order to; for the purpose of''.", "ex_ko": "미국 국회의사당 건물은 원래 조지 워싱턴의 유해를 보관하기 위해 설계되었습니다.", "ex_en": "The U.S. Capitol building was originally designed to hold George Washington''s remains."}, {"name": "~는 (present modifier)", "level": "Intermediate", "exp": "Verb form used before a noun. 표현하다 → 표현하는 (expressing). 표현하는 특별한 방법 = a special way of expressing.", "ex_ko": "이 계획은 초대 대통령에 대한 존경을 표현하는 특별한 방법이었습니다.", "ex_en": "This plan was a special way of expressing respect for the first president."}, {"name": "~ㄹ 수 있다", "level": "Intermediate", "exp": "Ability/possibility modal. Attaches to verb stem (내려다보다 → 내려다볼) to express ''be able to; can''.", "ex_ko": "국회는 방문객들이 워싱턴의 무덤을 내려다볼 수 있는 관람실을 특별히 설계했습니다.", "ex_en": "Congress specially designed a viewing room where visitors could look down at Washington''s tomb."}, {"name": "~도록", "level": "Intermediate", "exp": "Purpose/result marker; expresses ''so that; in order that''. Often used with potential forms (참배할 수 있도록).", "ex_ko": "이 관람실은 사람들이 위에서 아래를 보며 대통령의 무덤을 참배할 수 있도록 만들어진 공간이었습니다.", "ex_en": "This viewing room was a space created so that people could pay respects to the president''s tomb while looking down from above."}, {"name": "~아/어진 (passive modifier)", "level": "Intermediate", "exp": "Passive 만들어지다 used before a noun. 만들어진 공간 = a space that was made.", "ex_ko": "이 관람실은 사람들이 위에서 아래를 보며 대통령의 무덤을 참배할 수 있도록 만들어진 공간이었습니다.", "ex_en": "This viewing room was a space created so that people could pay respects to the president''s tomb while looking down from above."}, {"name": "~아/어 달라는", "level": "Intermediate", "exp": "Reports a request: ''asking (someone) to do''. 묻다 → 묻어 달라는 내용 (a request to bury him).", "ex_ko": "하지만 워싱턴의 유언장에는 자신을 마운트 버넌에 묻어달라는 내용이 적혀 있었습니다.", "ex_en": "However, Washington''s will contained a request to be buried at Mount Vernon."}, {"name": "~어 있다", "level": "Intermediate", "exp": "Stative auxiliary. Marks completed state or condition: ''be in a state of; have been written''.", "ex_ko": "하지만 워싱턴의 유언장에는 자신을 마운트 버넌에 묻어달라는 내용이 적혀 있었습니다.", "ex_en": "However, Washington''s will contained a request to be buried at Mount Vernon."}, {"name": "~고 싶어 하다", "level": "Intermediate", "exp": "Used for what someone else wants. 쉬다 → 쉬고 싶어 하다 (he wanted to rest).", "ex_ko": "그는 자신의 고향 땅에서 영원히 쉬고 싶어 했던 것입니다.", "ex_en": "He wanted to rest eternally in his homeland."}, {"name": "~았/었던 것이다", "level": "Intermediate", "exp": "Explains the reason behind something in the past: ''it was that…''. 싶어 하다 → 싶어 했던 것입니다.", "ex_ko": "그는 자신의 고향 땅에서 영원히 쉬고 싶어 했던 것입니다.", "ex_en": "He wanted to rest eternally in his homeland."}, {"name": "~았/었던 대로", "level": "Intermediate", "exp": "Means ''just as (someone) did''. 원하다 → 원했던 대로 (just as he wished).", "ex_ko": "오늘날 조지 워싱턴은 그가 원했던 대로 마운트 버넌에 잠들어 있습니다.", "ex_en": "Today George Washington rests at Mount Vernon just as he wished."}]}', updated_at = now() where article_id = 'mp00kpaictf7' and md5(translation) = '7012c63cf3275f82595f090e64e77fdd';
update public.article_cache set translation = '{"sentences": [{"text": "뉴욕시에는 약 300만 마리의 쥐가 살고 있는 것으로 추정됩니다.", "idx": 0, "translation": "It is estimated that approximately 3 million rats live in New York City.", "vocab": [{"ko": "약", "en": "approximately", "note": ""}, {"ko": "마리", "en": "counter for animals", "note": ""}, {"ko": "쥐", "en": "rat, mouse", "note": ""}, {"ko": "추정되다", "en": "to be estimated", "note": ""}], "analysis": [{"type": "grammar", "label": "~고 있다", "exp": "progressive aspect - is V-ing", "example_in_sentence": "살고 있는"}, {"type": "grammar", "label": "~(으)ㄴ/는 것으로 추정되다", "exp": "''It is estimated that ...''. 것으로 marks what is estimated: 살고 있다 → 살고 있는 것으로 추정됩니다.", "example_in_sentence": "살고 있는 것으로 추정됩니다"}, {"type": "grammar", "label": "~ㄴ/는", "exp": "present tense modifier for nouns", "example_in_sentence": "살고 있는"}, {"type": "grammar", "label": "~되다 (passive)", "exp": "되다 makes a 하다 verb passive: 추정하다 (to estimate) → 추정되다 (to be estimated) → 추정됩니다.", "example_in_sentence": "추정됩니다"}]}, {"text": "이는 정말 놀라운 숫자예요.", "idx": 1, "translation": "This is a truly surprising number.", "vocab": [{"ko": "정말", "en": "really, truly", "note": ""}, {"ko": "놀랍다", "en": "to be surprising", "note": ""}, {"ko": "숫자", "en": "number", "note": ""}], "analysis": [{"type": "grammar", "label": "ㅂ irregular + ~(으)ㄴ modifier", "exp": "Adjectives ending in ㅂ change ㅂ to 우 before -은: 놀랍다 → 놀라운 숫자 (a surprising number).", "example_in_sentence": "놀라운"}]}, {"text": "이 숫자를 사람 수와 비교해 보면 더욱 흥미로워집니다.", "idx": 2, "translation": "When you compare this number with the population, it becomes even more interesting.", "vocab": [{"ko": "비교하다", "en": "to compare", "note": ""}, {"ko": "흥미롭다", "en": "to be interesting", "note": ""}], "analysis": [{"type": "grammar", "label": "~아/어 보다", "exp": "attempt or experience - try V-ing / have done", "example_in_sentence": "비교해 보면"}, {"type": "grammar", "label": "~(으)면", "exp": "conditional - if / when", "example_in_sentence": "보면"}, {"type": "grammar", 